/* Blackboard lessons for the trigonometry cheat sheet: one lesson per card (and per row of the exact-values table).
   Each lesson: the idea with a graph or a unit-circle picture, a worked example, an exam-style exercise. Texts: 'en|fr|es|ja|zh'. */
(function () {
  const R = String.raw;
  const IDEA = 'The idea|L’idée|La idea|考え方|思路', EX = 'Worked example|Exemple résolu|Ejemplo resuelto|例題|例题', YOUR = 'Your turn|À vous|Te toca|やってみよう|轮到你了';
  const TRY = 'Work it out on paper, type the answer and check it. Each hint writes the next line of the solution on the board.|Faites le calcul sur papier, tapez la réponse et vérifiez. Chaque indice écrit la ligne suivante de la solution au tableau.|Hazlo en papel, escribe la respuesta y compruébala. Cada pista escribe en la pizarra la siguiente línea de la solución.|紙で計算し、答えを入力して確かめましょう。ヒントごとに解答が 1 行ずつ黒板に書かれます。|先在纸上算，输入答案并检查。每次提示会在黑板上写出解答的下一行。';
  const ROOTS = 'Give every solution in [0, 2π), separated by ;  (e.g. pi/6; 5pi/6).|Donnez toutes les solutions dans [0, 2π[, séparées par ;  (ex. pi/6; 5pi/6).|Da todas las soluciones en [0, 2π), separadas por ;  (p. ej. pi/6; 5pi/6).|[0, 2π) の解をすべて ; で区切って（例：pi/6; 5pi/6）。|写出 [0, 2π) 内所有解，用 ; 分隔（如 pi/6; 5pi/6）。';
  const F = (tex, o = {}) => ['w', R`\displaystyle ` + tex, Object.assign({ s: 26 }, o)];
  const Y = (tex, o = {}) => F(tex, Object.assign({ c: 'y' }, o));
  const W = (txt, o = {}) => ['t', txt, Object.assign({ s: 18, c: 'b' }, o)];
  const H = name => ['t', name, { head: true, s: 16, c: 'y' }];
  const AX = (xw, yw) => ['ax', { xw, yw }], P = (eq, c = 'y', o = {}) => ['p', eq, Object.assign({ c }, o)];
  // point labels are plain text: turn \tfrac{5\pi}6 into 5π/6
  const plain = t => String(t || '').replace(/\\tfrac\{([^{}]*)\}\{([^{}]*)\}/g, '$1/$2').replace(/\\tfrac\{([^{}]*)\}(\w)/g, '$1/$2').replace(/\\tfrac\\pi(\w)/g, 'π/$1').replace(/\\pi/g, 'π').replace(/[{}\\]/g, '');
  const PT = (x, y, lab, c = 'o') => ['pt', x, y, plain(lab), { c }];
  const LBL = (x, y, tex, c = 'y') => ['lbl', x, y, tex, { c }], LN = (x1, y1, x2, y2, c = 'chalk', o = {}) => ['ln', x1, y1, x2, y2, Object.assign({ c }, o)];
  const PI = Math.PI;
  // unit circle pictures in a flat scene
  const P2 = (x, y) => [x, y, 0];
  const UC = (extra = []) => [['3d', { flat: true, c: [0, 0, 0], r: 1.45 }], ['circ3', P2(0, 0), [0, 0, 1], 1, { c: 'b' }], ...extra];
  const RAY = (t, lab, c = 'y') => { const x = Math.cos(t), y = Math.sin(t); return [['vec', P2(0, 0), P2(x, y), { c }], ['seg', P2(x, y), P2(x, 0), { c: 'g', dash: true }], ['seg', P2(0, 0), P2(x, 0), { c: 'o', w: 3.4 }], ['seg', P2(x, 0), P2(x, y), { c: 'p', w: 3.4 }], ['pt3', P2(x, y), lab || '', { c }]]; };
  const TRI = (pts, labs = []) => [['3d', { flat: true, axes: false, c: [(pts[0][0] + pts[1][0] + pts[2][0]) / 3, (pts[0][1] + pts[1][1] + pts[2][1]) / 3, 0], r: Math.max(...pts.map(p => Math.abs(p[0]))) * 0.7 + 0.6 }], ['poly3', pts.map(p => P2(...p)), { c: 'b', fill: 0.16 }], ...labs.map(([x, y, t, c]) => ['lab3', P2(x, y), t, { c: c || 'y' }])];
  const L = {};
  const lesson = (key, head, idea, ex, your) => {
    L[key] = [{ t: IDEA, s: idea.s, a: [H(head), ...idea.a] }, { t: EX, s: ex.s, a: [['clr'], H(head), ...ex.a] },
      { t: YOUR, s: your.s || (your.ex.k === 'roots' ? ROOTS + ' ' : '') + TRY, a: [['clr'], H(head), ...(your.a || [])], ex: your.ex }];
    if (your.ex.k === 'roots') { const p = ROOTS.split('|'), t = TRY.split('|'); L[key][2].s = your.s || p.map((x, i) => x + ' ' + t[i]).join('|'); }
  };

  // =============================== Right-triangle ratios ===============================
  lesson('Right-triangle ratios/Sine, cosine, tangent', 'Sine, cosine, tangent|Sinus, cosinus, tangente|Seno, coseno, tangente|sin, cos, tan|正弦、余弦、正切',
    { s: R`In a right triangle, pick one acute angle $\theta$. The side across from it is the opposite, the side touching it is the adjacent, the longest side is the hypotenuse. Sine is opposite over hypotenuse, cosine is adjacent over hypotenuse, tangent is opposite over adjacent (SOH CAH TOA). The ratios depend only on the angle, not on the size of the triangle.|Dans un triangle rectangle, on choisit un angle aigu $\theta$. Le côté en face est l’opposé, celui qui le touche est l’adjacent, le plus long l’hypoténuse. Sinus = opposé / hypoténuse, cosinus = adjacent / hypoténuse, tangente = opposé / adjacent (SOH CAH TOA). Les rapports ne dépendent que de l’angle, pas de la taille du triangle.|En un triángulo rectángulo elige un ángulo agudo $\theta$. El lado de enfrente es el opuesto, el que lo toca es el contiguo y el más largo la hipotenusa. Seno = opuesto / hipotenusa, coseno = contiguo / hipotenusa, tangente = opuesto / contiguo. Las razones solo dependen del ángulo, no del tamaño del triángulo.|直角三角形で鋭角 $\theta$ を 1 つ選びます。向かいの辺が対辺、接する辺が隣辺、最長が斜辺。sin = 対辺/斜辺、cos = 隣辺/斜辺、tan = 対辺/隣辺。比は角だけで決まり、三角形の大きさによらない。|在直角三角形中取一个锐角 $\theta$。对着它的是对边，挨着它的是邻边，最长的是斜边。正弦 = 对边/斜边，余弦 = 邻边/斜边，正切 = 对边/邻边。这些比值只取决于角，与三角形大小无关。`,
      a: [F(R`\sin\theta = \frac{\text{opp}}{\text{hyp}},\ \cos\theta = \frac{\text{adj}}{\text{hyp}},\ \tan\theta = \frac{\text{opp}}{\text{adj}}`, { s: 24 }), W('SOH  CAH  TOA|SOH  CAH  TOA|SOH  CAH  TOA|SOH  CAH  TOA|SOH  CAH  TOA'), ...TRI([[0, 0], [4, 0], [4, 3]], [[2, -0.35, 'adj'], [4.45, 1.5, 'opp'], [1.7, 1.75, 'hyp'], [0.8, 0.22, 'θ', 'o']])] },
    { s: R`Triangle with sides 3, 4, 5 and $\theta$ opposite the side 3: $\sin\theta = \tfrac35$, $\cos\theta = \tfrac45$, $\tan\theta = \tfrac34$. A ladder of length 6 leaning at $60^\circ$ reaches a height $6\sin 60^\circ = 3\sqrt3$.|Triangle de côtés 3, 4, 5 et $\theta$ opposé au côté 3 : $\sin\theta = \tfrac35$, $\cos\theta = \tfrac45$, $\tan\theta = \tfrac34$.|Triángulo de lados 3, 4, 5 con $\theta$ opuesto al lado 3: $\sin\theta = \tfrac35$, $\cos\theta = \tfrac45$, $\tan\theta = \tfrac34$.|3 辺 3, 4, 5 で $\theta$ の対辺が 3：$\sin\theta = \tfrac35$, $\cos\theta = \tfrac45$, $\tan\theta = \tfrac34$。|三边 3、4、5，$\theta$ 的对边为 3：$\sin\theta = \tfrac35$，$\cos\theta = \tfrac45$，$\tan\theta = \tfrac34$。`,
      a: [F(R`\sin\theta = \tfrac35,\quad \cos\theta = \tfrac45,\quad \tan\theta = \tfrac34`), ...TRI([[0, 0], [4, 0], [4, 3]], [[2, -0.35, '4'], [4.35, 1.5, '3'], [1.7, 1.75, '5'], [0.8, 0.22, 'θ', 'o']])] },
    { a: [F(R`\text{ladder } 6,\ 60^\circ`), ...TRI([[0, 0], [3, 0], [3, 5.196]], [[1.2, 2.9, '6'], [3.4, 2.6, 'h'], [0.6, 0.25, '60°', 'o']])],
      ex: { k: 'val', v: '3sqrt(3)', q: R`A 6 m ladder leans against a wall, making $60^\circ$ with the ground. How high up the wall does it reach?|Une échelle de 6 m s’appuie contre un mur et fait $60^\circ$ avec le sol. À quelle hauteur arrive-t-elle ?|Una escalera de 6 m se apoya en una pared formando $60^\circ$ con el suelo. ¿A qué altura llega?|長さ 6 m のはしごが地面と $60^\circ$ をなして壁に立てかけてある。壁のどの高さまで届くか。|一架 6 m 长的梯子靠在墙上，与地面成 $60^\circ$。它能达到墙上多高？`,
        sol: [R`h = 6\sin 60^\circ`, R`= 6\cdot\tfrac{\sqrt3}{2} = 3\sqrt3 \approx 5.20`] } });

  lesson('Right-triangle ratios/Reciprocal ratios', 'Reciprocal ratios|Rapports inverses|Razones inversas|逆数の三角比|倒数三角比',
    { s: R`Cotangent, secant and cosecant are just one over tangent, cosine and sine. Nothing new to learn: compute the basic ratio, then flip it. They blow up where the basic ratio is 0.|Cotangente, sécante et cosécante sont simplement les inverses de la tangente, du cosinus et du sinus. Rien de nouveau : on calcule le rapport de base, puis on l’inverse. Elles explosent là où le rapport de base est nul.|Cotangente, secante y cosecante son solo uno entre la tangente, el coseno y el seno. Nada nuevo: calcula la razón básica y dale la vuelta. Se disparan donde la razón básica vale 0.|cot, sec, csc は tan, cos, sin の逆数にすぎません。基本の比を求めてひっくり返すだけ。基本の比が 0 のところで発散。|余切、正割、余割只是正切、余弦、正弦的倒数。没有新东西：算出基本比值再取倒数。在基本比值为 0 处它们趋于无穷。`,
      a: [F(R`\cot\theta = \frac{1}{\tan\theta},\ \sec\theta = \frac{1}{\cos\theta},\ \csc\theta = \frac{1}{\sin\theta}`, { s: 24 }), AX([-0.3, 3.2], [-1.5, 4]), P('y=cos(x)', 'b'), P('y=1/cos(x)', 'y', { d: 400 }), LBL(1.0, 2.3, R`\sec x`)] },
    { s: R`At $60^\circ$: $\cos = \tfrac12$ so $\sec = 2$; $\sin = \tfrac{\sqrt3}2$ so $\csc = \tfrac{2}{\sqrt3}$; $\tan = \sqrt3$ so $\cot = \tfrac{1}{\sqrt3}$.|À $60^\circ$ : $\cos = \tfrac12$ donc $\sec = 2$ ; $\sin = \tfrac{\sqrt3}2$ donc $\csc = \tfrac{2}{\sqrt3}$ ; $\tan = \sqrt3$ donc $\cot = \tfrac{1}{\sqrt3}$.|A $60^\circ$: $\cos = \tfrac12$, luego $\sec = 2$; $\sin = \tfrac{\sqrt3}2$, luego $\csc = \tfrac{2}{\sqrt3}$; $\tan = \sqrt3$, luego $\cot = \tfrac{1}{\sqrt3}$.|$60^\circ$ では $\cos = \tfrac12$ で $\sec = 2$、$\sin = \tfrac{\sqrt3}2$ で $\csc = \tfrac{2}{\sqrt3}$、$\tan = \sqrt3$ で $\cot = \tfrac{1}{\sqrt3}$。|在 $60^\circ$：$\cos = \tfrac12$，$\sec = 2$；$\sin = \tfrac{\sqrt3}2$，$\csc = \tfrac{2}{\sqrt3}$；$\tan = \sqrt3$，$\cot = \tfrac{1}{\sqrt3}$。`,
      a: [F(R`\sec 60^\circ = 2,\quad \csc 60^\circ = \tfrac{2}{\sqrt3}`), Y(R`\cot 60^\circ = \tfrac{1}{\sqrt3} = \tfrac{\sqrt3}{3}`), AX([-0.3, 3.2], [-1.5, 4]), P('y=cos(x)', 'b'), P('y=1/cos(x)', 'y'), PT(PI / 3, 2, R`(\tfrac\pi3, 2)`)] },
    { a: [F(R`\tan\theta = \tfrac34,\quad 0 < \theta < 90^\circ`), ...TRI([[0, 0], [4, 0], [4, 3]], [[2, -0.35, '4'], [4.35, 1.5, '3'], [1.7, 1.75, '?'], [0.8, 0.22, 'θ', 'o']])],
      ex: { k: 'val', v: '5/4', q: R`If $\tan\theta = \tfrac34$ and $\theta$ is acute, find $\sec\theta$.|Si $\tan\theta = \tfrac34$ et $\theta$ est aigu, calculez $\sec\theta$.|Si $\tan\theta = \tfrac34$ y $\theta$ es agudo, halla $\sec\theta$.|$\tan\theta = \tfrac34$（$\theta$ は鋭角）のとき $\sec\theta$ を求めよ。|若 $\tan\theta = \tfrac34$ 且 $\theta$ 为锐角，求 $\sec\theta$。`,
        sol: [R`\text{opp} = 3,\ \text{adj} = 4,\ \text{hyp} = 5`, R`\cos\theta = \tfrac45`, R`\sec\theta = \tfrac54`] } });

  lesson('Right-triangle ratios/Complementary angles', 'Complementary angles|Angles complémentaires|Ángulos complementarios|余角の公式|余角公式',
    { s: R`The two acute angles of a right triangle add up to $90^\circ$. The side opposite one of them is adjacent to the other, so the sine of one angle is the cosine of the other — that is where the “co” in cosine comes from.|Les deux angles aigus d’un triangle rectangle font $90^\circ$ à eux deux. Le côté opposé à l’un est adjacent à l’autre : le sinus de l’un est le cosinus de l’autre — d’où le « co » de cosinus.|Los dos ángulos agudos de un triángulo rectángulo suman $90^\circ$. El lado opuesto a uno es contiguo al otro, así que el seno de uno es el coseno del otro: de ahí el «co» de coseno.|直角三角形の 2 つの鋭角の和は $90^\circ$。一方の対辺はもう一方の隣辺なので、一方の sin はもう一方の cos。|直角三角形的两个锐角之和为 $90^\circ$。一个角的对边是另一个角的邻边，所以一个角的正弦等于另一个角的余弦——余弦的“余”就由此而来。`,
      a: [F(R`\sin(90^\circ - \theta) = \cos\theta`), F(R`\tan(90^\circ - \theta) = \frac{1}{\tan\theta}`), ...TRI([[0, 0], [4, 0], [4, 3]], [[0.8, 0.22, 'θ', 'o'], [3.75, 2.2, '90° − θ', 'g']])] },
    { s: R`$\cos 50^\circ = \sin 40^\circ$ and $\tan 70^\circ\cdot\tan 20^\circ = 1$. Spotting complementary pairs often makes an expression collapse to a number.|$\cos 50^\circ = \sin 40^\circ$ et $\tan 70^\circ\cdot\tan 20^\circ = 1$. Repérer les paires complémentaires fait souvent s’effondrer une expression en un nombre.|$\cos 50^\circ = \sin 40^\circ$ y $\tan 70^\circ\cdot\tan 20^\circ = 1$. Detectar pares complementarios suele reducir una expresión a un número.|$\cos 50^\circ = \sin 40^\circ$、$\tan 70^\circ\cdot\tan 20^\circ = 1$。余角の組を見つけると式が数になることが多い。|$\cos 50^\circ = \sin 40^\circ$，$\tan 70^\circ\cdot\tan 20^\circ = 1$。发现互余的一对常能把式子化成一个数。`,
      a: [F(R`\cos 50^\circ = \sin 40^\circ`), Y(R`\tan 70^\circ\cdot\tan 20^\circ = 1`)] },
    { a: [F(R`\frac{\sin 20^\circ}{\cos 70^\circ}`)],
      ex: { k: 'val', v: '1', q: R`Compute $\dfrac{\sin 20^\circ}{\cos 70^\circ}$ without a calculator.|Calculez $\dfrac{\sin 20^\circ}{\cos 70^\circ}$ sans calculatrice.|Calcula $\dfrac{\sin 20^\circ}{\cos 70^\circ}$ sin calculadora.|電卓なしで $\dfrac{\sin 20^\circ}{\cos 70^\circ}$ を求めよ。|不用计算器求 $\dfrac{\sin 20^\circ}{\cos 70^\circ}$。`,
        sol: [R`\cos 70^\circ = \sin(90^\circ - 70^\circ) = \sin 20^\circ`, R`\frac{\sin 20^\circ}{\sin 20^\circ} = 1`] } });

  // =============================== The unit circle ===============================
  lesson('The unit circle/Coordinates of the point', 'The unit circle|Le cercle trigonométrique|La circunferencia unidad|単位円|单位圆',
    { s: R`Turn by the angle $\theta$ from the positive $x$-axis on a circle of radius 1. The point you reach has coordinates $(\cos\theta, \sin\theta)$: cosine is the horizontal part (orange), sine the vertical part (pink). This works for every angle, not only acute ones.|On tourne de l’angle $\theta$ à partir de l’axe des $x$ positifs sur un cercle de rayon 1. Le point atteint a pour coordonnées $(\cos\theta, \sin\theta)$ : le cosinus est la partie horizontale (orange), le sinus la partie verticale (rose). C’est valable pour tout angle, pas seulement aigu.|Gira el ángulo $\theta$ desde el semieje $x$ positivo sobre una circunferencia de radio 1. El punto al que llegas tiene coordenadas $(\cos\theta, \sin\theta)$: el coseno es la parte horizontal (naranja) y el seno la vertical (rosa). Vale para cualquier ángulo, no solo agudos.|半径 1 の円で $x$ 軸の正の向きから角 $\theta$ だけ回ると、着いた点の座標が $(\cos\theta, \sin\theta)$：cos が横（オレンジ）、sin が縦（ピンク）。鋭角に限らずどの角でも成り立つ。|在半径为 1 的圆上从 $x$ 轴正方向转过角 $\theta$，到达的点坐标为 $(\cos\theta, \sin\theta)$：余弦是水平部分（橙），正弦是竖直部分（粉）。对任何角都成立，不只锐角。`,
      a: [F(R`P = (\cos\theta, \sin\theta)`, { s: 30 }), F(R`\tan\theta = \frac{\sin\theta}{\cos\theta}`), W('orange: cos θ, pink: sin θ|orange : cos θ, rose : sin θ|naranja: cos θ, rosa: sin θ|オレンジ：cos θ、ピンク：sin θ|橙：cos θ，粉：sin θ'), ...UC(RAY(0.9, 'P'))] },
    { s: R`At $120^\circ$ the point is in the second quadrant, mirrored from $60^\circ$: $(-\tfrac12, \tfrac{\sqrt3}2)$. So $\cos 120^\circ = -\tfrac12$, $\sin 120^\circ = \tfrac{\sqrt3}2$ and $\tan 120^\circ = -\sqrt3$.|À $120^\circ$ le point est dans le deuxième quadrant, symétrique de $60^\circ$ : $(-\tfrac12, \tfrac{\sqrt3}2)$. Donc $\cos 120^\circ = -\tfrac12$, $\sin 120^\circ = \tfrac{\sqrt3}2$ et $\tan 120^\circ = -\sqrt3$.|A $120^\circ$ el punto está en el segundo cuadrante, simétrico de $60^\circ$: $(-\tfrac12, \tfrac{\sqrt3}2)$. Así $\cos 120^\circ = -\tfrac12$, $\sin 120^\circ = \tfrac{\sqrt3}2$ y $\tan 120^\circ = -\sqrt3$.|$120^\circ$ の点は第 2 象限、$60^\circ$ の鏡像で $(-\tfrac12, \tfrac{\sqrt3}2)$。$\cos 120^\circ = -\tfrac12$, $\sin 120^\circ = \tfrac{\sqrt3}2$, $\tan 120^\circ = -\sqrt3$。|$120^\circ$ 的点在第二象限，与 $60^\circ$ 对称：$(-\tfrac12, \tfrac{\sqrt3}2)$。所以 $\cos 120^\circ = -\tfrac12$，$\sin 120^\circ = \tfrac{\sqrt3}2$，$\tan 120^\circ = -\sqrt3$。`,
      a: [Y(R`P_{120^\circ} = \left(-\tfrac12, \tfrac{\sqrt3}2\right)`), F(R`\tan 120^\circ = \frac{\sqrt3/2}{-1/2} = -\sqrt3`), ...UC([...RAY(2 * PI / 3, '120°'), ['seg', P2(0, 0), P2(0.5, Math.sqrt(3) / 2), { c: 'chalk', dash: true }]])] },
    { a: [F(R`\theta = 150^\circ`), ...UC([['vec', P2(0, 0), P2(Math.cos(5 * PI / 6), Math.sin(5 * PI / 6)), { c: 'y' }]])],
      ex: { k: 'pt', v: ['-sqrt(3)/2', '1/2'], q: R`Give the coordinates of the point of the unit circle at $150^\circ$.|Donnez les coordonnées du point du cercle trigonométrique à $150^\circ$.|Da las coordenadas del punto de la circunferencia unidad a $150^\circ$.|単位円上で $150^\circ$ の点の座標を答えよ。|写出单位圆上 $150^\circ$ 处点的坐标。`,
        sol: [R`150^\circ = 180^\circ - 30^\circ`, R`\cos 150^\circ = -\cos 30^\circ = -\tfrac{\sqrt3}2,\quad \sin 150^\circ = \sin 30^\circ = \tfrac12`, R`\left(-\tfrac{\sqrt3}2, \tfrac12\right)`] } });

  lesson('The unit circle/Pythagorean identities', 'Pythagorean identities|Relations de Pythagore|Identidades pitagóricas|三角関数の相互関係|勾股恒等式',
    { s: R`The point $(\cos\theta, \sin\theta)$ is on the circle of radius 1, so by Pythagoras $\cos^2\theta + \sin^2\theta = 1$. Dividing by $\cos^2\theta$ gives the second identity. Use them to find one ratio from another; the quadrant decides the sign.|Le point $(\cos\theta, \sin\theta)$ est sur le cercle de rayon 1, donc par Pythagore $\cos^2\theta + \sin^2\theta = 1$. En divisant par $\cos^2\theta$ on obtient la seconde relation. On s’en sert pour trouver un rapport à partir d’un autre ; le quadrant décide du signe.|El punto $(\cos\theta, \sin\theta)$ está en la circunferencia de radio 1, así que por Pitágoras $\cos^2\theta + \sin^2\theta = 1$. Dividiendo entre $\cos^2\theta$ sale la segunda identidad. Sirven para hallar una razón a partir de otra; el cuadrante decide el signo.|点 $(\cos\theta, \sin\theta)$ は半径 1 の円上なので三平方の定理で $\cos^2\theta + \sin^2\theta = 1$。$\cos^2\theta$ で割れば 2 つ目。ある比から別の比を求めるのに使い、符号は象限で決める。|点 $(\cos\theta, \sin\theta)$ 在半径 1 的圆上，由勾股定理 $\cos^2\theta + \sin^2\theta = 1$。两边除以 $\cos^2\theta$ 得第二个恒等式。用它们由一个比值求另一个；符号由象限决定。`,
      a: [Y(R`\sin^2\theta + \cos^2\theta = 1`, { s: 30 }), F(R`1 + \tan^2\theta = \frac{1}{\cos^2\theta}`), W('the quadrant decides the sign|le quadrant décide du signe|el cuadrante decide el signo|符号は象限で決まる|象限决定符号'), ...UC(RAY(0.9, 'P'))] },
    { s: R`$\sin\theta = \tfrac35$ with $\theta$ in the second quadrant: $\cos^2\theta = 1 - \tfrac{9}{25} = \tfrac{16}{25}$, and cosine is negative there, so $\cos\theta = -\tfrac45$ and $\tan\theta = -\tfrac34$.|$\sin\theta = \tfrac35$ avec $\theta$ dans le deuxième quadrant : $\cos^2\theta = 1 - \tfrac{9}{25} = \tfrac{16}{25}$, et le cosinus y est négatif, donc $\cos\theta = -\tfrac45$ et $\tan\theta = -\tfrac34$.|$\sin\theta = \tfrac35$ con $\theta$ en el segundo cuadrante: $\cos^2\theta = 1 - \tfrac{9}{25} = \tfrac{16}{25}$, y allí el coseno es negativo, así que $\cos\theta = -\tfrac45$ y $\tan\theta = -\tfrac34$.|$\sin\theta = \tfrac35$、$\theta$ は第 2 象限：$\cos^2\theta = \tfrac{16}{25}$、そこで cos は負なので $\cos\theta = -\tfrac45$、$\tan\theta = -\tfrac34$。|$\sin\theta = \tfrac35$，$\theta$ 在第二象限：$\cos^2\theta = \tfrac{16}{25}$，该象限余弦为负，所以 $\cos\theta = -\tfrac45$，$\tan\theta = -\tfrac34$。`,
      a: [F(R`\cos^2\theta = 1 - \tfrac{9}{25} = \tfrac{16}{25}`), Y(R`\text{QII}:\ \cos\theta = -\tfrac45`), F(R`\tan\theta = -\tfrac34`), ...UC(RAY(PI - Math.asin(0.6), 'P'))] },
    { a: [F(R`\cos\theta = -\tfrac{5}{13},\quad \pi < \theta < \tfrac{3\pi}{2}`), ...UC([['vec', P2(0, 0), P2(-5 / 13, -12 / 13), { c: 'y' }]])],
      ex: { k: 'val', v: '12/5', q: R`$\cos\theta = -\tfrac{5}{13}$ and $\theta$ is in the third quadrant. Find $\tan\theta$.|$\cos\theta = -\tfrac{5}{13}$ et $\theta$ est dans le troisième quadrant. Calculez $\tan\theta$.|$\cos\theta = -\tfrac{5}{13}$ y $\theta$ está en el tercer cuadrante. Halla $\tan\theta$.|$\cos\theta = -\tfrac{5}{13}$、$\theta$ は第 3 象限。$\tan\theta$ を求めよ。|$\cos\theta = -\tfrac{5}{13}$，$\theta$ 在第三象限，求 $\tan\theta$。`,
        sol: [R`\sin^2\theta = 1 - \tfrac{25}{169} = \tfrac{144}{169}`, R`\text{QIII}:\ \sin\theta = -\tfrac{12}{13}`, R`\tan\theta = \frac{-12/13}{-5/13} = \tfrac{12}{5}`] } });

  lesson('The unit circle/Signs by quadrant', 'Signs by quadrant|Signes selon le quadrant|Signos por cuadrante|象限と符号|各象限的符号',
    { s: R`Cosine is the $x$-coordinate and sine the $y$-coordinate, so their signs follow the quadrant. Tangent is their quotient: positive when both have the same sign (I and III). A memory aid: “All Students Take Calculus” — All, Sine, Tangent, Cosine are positive in quadrants I, II, III, IV.|Le cosinus est l’abscisse et le sinus l’ordonnée : leurs signes suivent le quadrant. La tangente est leur quotient : positive quand ils ont le même signe (I et III). Moyen mnémotechnique : I tout positif, II sinus, III tangente, IV cosinus.|El coseno es la coordenada $x$ y el seno la $y$, así que sus signos siguen el cuadrante. La tangente es su cociente: positiva cuando tienen el mismo signo (I y III). Regla: I todas, II seno, III tangente, IV coseno.|cos は $x$ 座標、sin は $y$ 座標なので、符号は象限で決まる。tan はその比で、同符号（I と III）のとき正。I は全部、II は sin、III は tan、IV は cos が正。|余弦是 $x$ 坐标，正弦是 $y$ 坐标，符号随象限而定。正切是二者之比：同号时（I、III）为正。口诀：一全正、二正弦、三正切、四余弦。`,
      a: [F(R`\text{I: all} > 0,\ \text{II: }\sin,\ \text{III: }\tan,\ \text{IV: }\cos`, { s: 24 }), ...UC([['lab3', P2(0.55, 0.55), 'I: +++', { c: 'g' }], ['lab3', P2(-0.95, 0.55), 'II: sin', { c: 'y' }], ['lab3', P2(-0.95, -0.6), 'III: tan', { c: 'o' }], ['lab3', P2(0.45, -0.6), 'IV: cos', { c: 'p' }]])] },
    { s: R`$\theta = 300^\circ$ is in quadrant IV: cosine positive, sine and tangent negative. Indeed $\cos 300^\circ = \tfrac12$, $\sin 300^\circ = -\tfrac{\sqrt3}2$.|$\theta = 300^\circ$ est dans le quadrant IV : cosinus positif, sinus et tangente négatifs. En effet $\cos 300^\circ = \tfrac12$, $\sin 300^\circ = -\tfrac{\sqrt3}2$.|$\theta = 300^\circ$ está en el cuadrante IV: coseno positivo, seno y tangente negativos. En efecto $\cos 300^\circ = \tfrac12$, $\sin 300^\circ = -\tfrac{\sqrt3}2$.|$\theta = 300^\circ$ は第 4 象限：cos は正、sin と tan は負。実際 $\cos 300^\circ = \tfrac12$, $\sin 300^\circ = -\tfrac{\sqrt3}2$。|$\theta = 300^\circ$ 在第四象限：余弦为正，正弦和正切为负。确实 $\cos 300^\circ = \tfrac12$，$\sin 300^\circ = -\tfrac{\sqrt3}2$。`,
      a: [F(R`300^\circ \in \text{IV}`), Y(R`\cos > 0,\ \sin < 0,\ \tan < 0`), ...UC(RAY(5 * PI / 3, '300°'))] },
    { a: [F(R`\sin\theta = 0.6,\quad \cos\theta < 0`)],
      ex: { k: 'val', v: '-0.75', q: R`$\sin\theta = 0.6$ and $\cos\theta < 0$. Find $\tan\theta$.|$\sin\theta = 0{,}6$ et $\cos\theta < 0$. Calculez $\tan\theta$.|$\sin\theta = 0{,}6$ y $\cos\theta < 0$. Halla $\tan\theta$.|$\sin\theta = 0.6$、$\cos\theta < 0$ のとき $\tan\theta$ を求めよ。|$\sin\theta = 0.6$，$\cos\theta < 0$，求 $\tan\theta$。`,
        sol: [R`\sin > 0,\ \cos < 0 \Rightarrow \text{QII}`, R`\cos\theta = -\sqrt{1 - 0.36} = -0.8`, R`\tan\theta = \frac{0.6}{-0.8} = -0.75`] } });

  lesson('The unit circle/Periods', 'Periods|Périodes|Periodos|周期|周期',
    { s: R`A full turn ($2\pi$) brings you back to the same point, so sine and cosine repeat every $2\pi$. Tangent already repeats after half a turn, because the opposite point has both signs flipped. Inside, $\sin(\omega x)$ squeezes the graph: its period is $\tfrac{2\pi}{\omega}$.|Un tour complet ($2\pi$) ramène au même point : sinus et cosinus se répètent tous les $2\pi$. La tangente se répète dès le demi-tour, car le point opposé a les deux signes inversés. Dans $\sin(\omega x)$, le graphe est comprimé : période $\tfrac{2\pi}{\omega}$.|Una vuelta completa ($2\pi$) devuelve al mismo punto, así que seno y coseno se repiten cada $2\pi$. La tangente ya se repite tras media vuelta, porque el punto opuesto tiene ambos signos cambiados. En $\sin(\omega x)$ la gráfica se comprime: periodo $\tfrac{2\pi}{\omega}$.|1 回転（$2\pi$）で同じ点に戻るので sin と cos の周期は $2\pi$。tan は半回転で繰り返す（反対側の点は両方の符号が逆）。$\sin(\omega x)$ はグラフが縮み、周期 $\tfrac{2\pi}{\omega}$。|转一整圈（$2\pi$）回到同一点，所以正弦、余弦每 $2\pi$ 重复一次。正切半圈就重复，因为对面的点两个符号都相反。$\sin(\omega x)$ 的图像被压缩，周期为 $\tfrac{2\pi}{\omega}$。`,
      a: [F(R`\sin, \cos:\ 2\pi,\qquad \tan:\ \pi`), Y(R`\sin(\omega x):\ T = \frac{2\pi}{\omega}`), AX([-0.5, 13], [-1.6, 1.6]), P('y=sin(x)'), P('y=sin(2x)', 'b', { d: 400 }), LBL(1.6, 1.25, R`\sin x`), LBL(0.4, -1.35, R`\sin 2x`, 'b')] },
    { s: R`$\sin(3x)$ has period $\tfrac{2\pi}{3}$: three full waves fit in $[0, 2\pi]$. $\tan(x + \pi) = \tan x$, so a tangent graph repeats every $\pi$.|$\sin(3x)$ a pour période $\tfrac{2\pi}{3}$ : trois ondulations complètes dans $[0, 2\pi]$. $\tan(x + \pi) = \tan x$ : la tangente se répète tous les $\pi$.|$\sin(3x)$ tiene periodo $\tfrac{2\pi}{3}$: caben tres ondas completas en $[0, 2\pi]$. $\tan(x + \pi) = \tan x$: la tangente se repite cada $\pi$.|$\sin(3x)$ の周期は $\tfrac{2\pi}{3}$：$[0, 2\pi]$ に 3 波入る。$\tan(x + \pi) = \tan x$ なので tan の周期は $\pi$。|$\sin(3x)$ 的周期为 $\tfrac{2\pi}{3}$：$[0, 2\pi]$ 内有三个完整波形。$\tan(x + \pi) = \tan x$，正切每 $\pi$ 重复。`,
      a: [Y(R`T(\sin 3x) = \frac{2\pi}{3}`), F(R`\tan(x + \pi) = \tan x`), AX([-0.3, 6.6], [-1.6, 1.6]), P('y=sin(3x)'), PT(2 * PI / 3, 0, R`\tfrac{2\pi}{3}`)] },
    { a: [F(R`y = \tan(2x)`), AX([-0.2, 3.4], [-4, 4]), P('y=tan(2x)')],
      ex: { k: 'val', v: 'pi/2', q: R`What is the period of $y = \tan(2x)$?|Quelle est la période de $y = \tan(2x)$ ?|¿Cuál es el periodo de $y = \tan(2x)$?|$y = \tan(2x)$ の周期を求めよ。|$y = \tan(2x)$ 的周期是多少？`,
        sol: [R`\tan:\ T = \pi`, R`\tan(2x):\ T = \frac{\pi}{2}`] } });

  // =============================== Exact values ===============================
  lesson('Exact values/Degrees', 'Degrees and radians|Degrés et radians|Grados y radianes|度とラジアン|角度与弧度',
    { s: R`Half a turn is $180^\circ = \pi$ radians. So multiply degrees by $\tfrac{\pi}{180}$ to get radians, and radians by $\tfrac{180}{\pi}$ to get degrees. Learn the key angles in both: $30^\circ = \tfrac\pi6$, $45^\circ = \tfrac\pi4$, $60^\circ = \tfrac\pi3$, $90^\circ = \tfrac\pi2$.|Un demi-tour vaut $180^\circ = \pi$ radians. On multiplie donc des degrés par $\tfrac{\pi}{180}$ pour avoir des radians, et des radians par $\tfrac{180}{\pi}$ pour des degrés. À connaître : $30^\circ = \tfrac\pi6$, $45^\circ = \tfrac\pi4$, $60^\circ = \tfrac\pi3$, $90^\circ = \tfrac\pi2$.|Media vuelta son $180^\circ = \pi$ radianes. Multiplica grados por $\tfrac{\pi}{180}$ para pasar a radianes, y radianes por $\tfrac{180}{\pi}$ para pasar a grados. Apréndete: $30^\circ = \tfrac\pi6$, $45^\circ = \tfrac\pi4$, $60^\circ = \tfrac\pi3$, $90^\circ = \tfrac\pi2$.|半回転は $180^\circ = \pi$ ラジアン。度に $\tfrac{\pi}{180}$ を掛けるとラジアン、ラジアンに $\tfrac{180}{\pi}$ を掛けると度。$30^\circ = \tfrac\pi6$, $45^\circ = \tfrac\pi4$, $60^\circ = \tfrac\pi3$, $90^\circ = \tfrac\pi2$ は覚える。|半圈是 $180^\circ = \pi$ 弧度。角度乘以 $\tfrac{\pi}{180}$ 得弧度，弧度乘以 $\tfrac{180}{\pi}$ 得角度。记住：$30^\circ = \tfrac\pi6$，$45^\circ = \tfrac\pi4$，$60^\circ = \tfrac\pi3$，$90^\circ = \tfrac\pi2$。`,
      a: [Y(R`180^\circ = \pi\ \text{rad}`), F(R`30^\circ = \tfrac\pi6,\ 45^\circ = \tfrac\pi4,\ 60^\circ = \tfrac\pi3,\ 90^\circ = \tfrac\pi2`, { s: 24 }), ...UC([['vec', P2(0, 0), P2(Math.cos(PI / 6), 0.5), { c: 'y' }], ['vec', P2(0, 0), P2(Math.SQRT1_2, Math.SQRT1_2), { c: 'g' }], ['vec', P2(0, 0), P2(0.5, Math.cos(PI / 6)), { c: 'o' }], ['lab3', P2(1.05, 0.55), 'π/6', { c: 'y' }], ['lab3', P2(0.75, 0.8), 'π/4', { c: 'g' }], ['lab3', P2(0.45, 1.05), 'π/3', { c: 'o' }]])] },
    { s: R`$225^\circ = 225\cdot\tfrac{\pi}{180} = \tfrac{5\pi}{4}$, and $\tfrac{7\pi}{6} = \tfrac{7\cdot 180^\circ}{6} = 210^\circ$.|$225^\circ = 225\cdot\tfrac{\pi}{180} = \tfrac{5\pi}{4}$, et $\tfrac{7\pi}{6} = \tfrac{7\cdot 180^\circ}{6} = 210^\circ$.|$225^\circ = 225\cdot\tfrac{\pi}{180} = \tfrac{5\pi}{4}$, y $\tfrac{7\pi}{6} = \tfrac{7\cdot 180^\circ}{6} = 210^\circ$.|$225^\circ = \tfrac{5\pi}{4}$、$\tfrac{7\pi}{6} = 210^\circ$。|$225^\circ = \tfrac{5\pi}{4}$，$\tfrac{7\pi}{6} = 210^\circ$。`,
      a: [F(R`225^\circ = 225\cdot\frac{\pi}{180} = \frac{5\pi}{4}`), Y(R`\frac{7\pi}{6} = \frac{7\cdot 180^\circ}{6} = 210^\circ`)] },
    { a: [F(R`150^\circ`)],
      ex: { k: 'val', v: '5pi/6', q: R`Convert $150^\circ$ to radians.|Convertissez $150^\circ$ en radians.|Pasa $150^\circ$ a radianes.|$150^\circ$ をラジアンに直せ。|把 $150^\circ$ 化为弧度。`,
        sol: [R`150\cdot\frac{\pi}{180}`, R`= \frac{5\pi}{6}`] } });

  lesson('Exact values/15° and 75°', '15° and 75°|15° et 75°|15° y 75°|15° と 75°|15° 与 75°',
    { s: R`$15^\circ = 45^\circ - 30^\circ$ and $75^\circ = 45^\circ + 30^\circ$, so the addition formulas give their exact values from the values you already know. Note $\sin 75^\circ = \cos 15^\circ$ (complementary angles).|$15^\circ = 45^\circ - 30^\circ$ et $75^\circ = 45^\circ + 30^\circ$ : les formules d’addition donnent leurs valeurs exactes à partir de valeurs connues. Remarquez $\sin 75^\circ = \cos 15^\circ$ (angles complémentaires).|$15^\circ = 45^\circ - 30^\circ$ y $75^\circ = 45^\circ + 30^\circ$, así que las fórmulas de la suma dan sus valores exactos a partir de los que ya conoces. Observa que $\sin 75^\circ = \cos 15^\circ$ (complementarios).|$15^\circ = 45^\circ - 30^\circ$、$75^\circ = 45^\circ + 30^\circ$ なので、加法定理で既知の値から厳密値が出る。$\sin 75^\circ = \cos 15^\circ$（余角）にも注意。|$15^\circ = 45^\circ - 30^\circ$，$75^\circ = 45^\circ + 30^\circ$，用和差公式由已知值得到精确值。注意 $\sin 75^\circ = \cos 15^\circ$（互余）。`,
      a: [F(R`15^\circ = 45^\circ - 30^\circ,\quad 75^\circ = 45^\circ + 30^\circ`), Y(R`\sin 15^\circ = \frac{\sqrt6 - \sqrt2}{4},\ \cos 15^\circ = \frac{\sqrt6 + \sqrt2}{4}`, { s: 24 })] },
    { s: R`$\cos 15^\circ = \cos 45^\circ\cos 30^\circ + \sin 45^\circ\sin 30^\circ = \tfrac{\sqrt2}2\cdot\tfrac{\sqrt3}2 + \tfrac{\sqrt2}2\cdot\tfrac12 = \tfrac{\sqrt6 + \sqrt2}{4} \approx 0.966$.|$\cos 15^\circ = \cos 45^\circ\cos 30^\circ + \sin 45^\circ\sin 30^\circ = \tfrac{\sqrt2}2\cdot\tfrac{\sqrt3}2 + \tfrac{\sqrt2}2\cdot\tfrac12 = \tfrac{\sqrt6 + \sqrt2}{4} \approx 0{,}966$.|$\cos 15^\circ = \cos 45^\circ\cos 30^\circ + \sin 45^\circ\sin 30^\circ = \tfrac{\sqrt2}2\cdot\tfrac{\sqrt3}2 + \tfrac{\sqrt2}2\cdot\tfrac12 = \tfrac{\sqrt6 + \sqrt2}{4} \approx 0{,}966$.|$\cos 15^\circ = \cos 45^\circ\cos 30^\circ + \sin 45^\circ\sin 30^\circ = \tfrac{\sqrt6 + \sqrt2}{4} \approx 0.966$。|$\cos 15^\circ = \cos 45^\circ\cos 30^\circ + \sin 45^\circ\sin 30^\circ = \tfrac{\sqrt6 + \sqrt2}{4} \approx 0.966$。`,
      a: [F(R`\cos(45^\circ - 30^\circ) = \tfrac{\sqrt2}2\cdot\tfrac{\sqrt3}2 + \tfrac{\sqrt2}2\cdot\tfrac12`), Y(R`= \frac{\sqrt6 + \sqrt2}{4}`)] },
    { a: [F(R`\sin 75^\circ`)],
      ex: { k: 'val', v: '(sqrt(6)+sqrt(2))/4', q: R`Find the exact value of $\sin 75^\circ$.|Donnez la valeur exacte de $\sin 75^\circ$.|Halla el valor exacto de $\sin 75^\circ$.|$\sin 75^\circ$ の厳密な値を求めよ。|求 $\sin 75^\circ$ 的精确值。`,
        sol: [R`\sin(45^\circ + 30^\circ) = \sin 45^\circ\cos 30^\circ + \cos 45^\circ\sin 30^\circ`, R`= \tfrac{\sqrt2}2\cdot\tfrac{\sqrt3}2 + \tfrac{\sqrt2}2\cdot\tfrac12`, R`= \frac{\sqrt6 + \sqrt2}{4}`] } });

  // the three rows of the exact-values table
  const ROW = (fn, plot, exq, exv, exsol, story) => ({
    s: story, a: [AX([-0.3, 3.5], fn === 'tan' ? [-1, 3] : [-1.2, 1.2]), P('y=' + plot), PT(PI / 6, NUMS[fn][0], R`\tfrac\pi6`), PT(PI / 4, NUMS[fn][1], R`\tfrac\pi4`), PT(PI / 3, NUMS[fn][2], R`\tfrac\pi3`)], exq, exv, exsol });
  const NUMS = { sin: [0.5, Math.SQRT1_2, Math.sqrt(3) / 2], cos: [Math.sqrt(3) / 2, Math.SQRT1_2, 0.5], tan: [1 / Math.sqrt(3), 1, Math.sqrt(3)] };
  const tableLesson = (key, head, idea, exS, exA, q, v, sol) => lesson(key, head, idea, { s: exS, a: exA }, { ex: { k: 'val', v, q, sol } });
  tableLesson(R`Exact values/\sin`, R`sin: exact values|sin : valeurs exactes|sin: valores exactos|sin の値|sin 的特殊值`,
    { s: R`A memory trick: $\sin 0, \tfrac\pi6, \tfrac\pi4, \tfrac\pi3, \tfrac\pi2$ are $\tfrac{\sqrt0}2, \tfrac{\sqrt1}2, \tfrac{\sqrt2}2, \tfrac{\sqrt3}2, \tfrac{\sqrt4}2$. The values climb from 0 to 1 as the point rises on the unit circle. Other angles come back to these by symmetry.|Astuce : $\sin 0, \tfrac\pi6, \tfrac\pi4, \tfrac\pi3, \tfrac\pi2$ valent $\tfrac{\sqrt0}2, \tfrac{\sqrt1}2, \tfrac{\sqrt2}2, \tfrac{\sqrt3}2, \tfrac{\sqrt4}2$. Les valeurs montent de 0 à 1 quand le point s’élève sur le cercle. Les autres angles s’y ramènent par symétrie.|Truco: $\sin 0, \tfrac\pi6, \tfrac\pi4, \tfrac\pi3, \tfrac\pi2$ valen $\tfrac{\sqrt0}2, \tfrac{\sqrt1}2, \tfrac{\sqrt2}2, \tfrac{\sqrt3}2, \tfrac{\sqrt4}2$. Suben de 0 a 1 al subir el punto por la circunferencia. Los demás ángulos se reducen a estos por simetría.|覚え方：$\sin 0, \tfrac\pi6, \tfrac\pi4, \tfrac\pi3, \tfrac\pi2$ は $\tfrac{\sqrt0}2, \tfrac{\sqrt1}2, \tfrac{\sqrt2}2, \tfrac{\sqrt3}2, \tfrac{\sqrt4}2$。点が円を上るにつれ 0 から 1 へ。他の角は対称性でこれに帰着。|记法：$\sin 0, \tfrac\pi6, \tfrac\pi4, \tfrac\pi3, \tfrac\pi2$ 依次为 $\tfrac{\sqrt0}2, \tfrac{\sqrt1}2, \tfrac{\sqrt2}2, \tfrac{\sqrt3}2, \tfrac{\sqrt4}2$。点在圆上升高时值从 0 增到 1。其他角用对称性化归到这些。`,
      a: [F(R`\sin:\ \tfrac{\sqrt0}2,\ \tfrac{\sqrt1}2,\ \tfrac{\sqrt2}2,\ \tfrac{\sqrt3}2,\ \tfrac{\sqrt4}2`), ...ROW('sin', 'sin(x)').a] },
    R`$\sin\tfrac{2\pi}{3}$: $\tfrac{2\pi}3 = \pi - \tfrac\pi3$ and $\sin(\pi - x) = \sin x$, so it equals $\sin\tfrac\pi3 = \tfrac{\sqrt3}2$.|$\sin\tfrac{2\pi}{3}$ : $\tfrac{2\pi}3 = \pi - \tfrac\pi3$ et $\sin(\pi - x) = \sin x$, donc cela vaut $\sin\tfrac\pi3 = \tfrac{\sqrt3}2$.|$\sin\tfrac{2\pi}{3}$: $\tfrac{2\pi}3 = \pi - \tfrac\pi3$ y $\sin(\pi - x) = \sin x$, así que vale $\sin\tfrac\pi3 = \tfrac{\sqrt3}2$.|$\sin\tfrac{2\pi}{3}$：$\tfrac{2\pi}3 = \pi - \tfrac\pi3$、$\sin(\pi - x) = \sin x$ より $\tfrac{\sqrt3}2$。|$\sin\tfrac{2\pi}{3}$：$\tfrac{2\pi}3 = \pi - \tfrac\pi3$，$\sin(\pi - x) = \sin x$，所以等于 $\tfrac{\sqrt3}2$。`,
    [F(R`\sin\frac{2\pi}{3} = \sin\left(\pi - \frac\pi3\right) = \sin\frac\pi3`), Y(R`= \frac{\sqrt3}{2}`), AX([-0.3, 3.5], [-1.2, 1.2]), P('y=sin(x)'), PT(PI / 3, Math.sqrt(3) / 2, ''), PT(2 * PI / 3, Math.sqrt(3) / 2, R`\tfrac{2\pi}3`)],
    R`Find $\sin\tfrac{5\pi}{6}$.|Calculez $\sin\tfrac{5\pi}{6}$.|Calcula $\sin\tfrac{5\pi}{6}$.|$\sin\tfrac{5\pi}{6}$ を求めよ。|求 $\sin\tfrac{5\pi}{6}$。`, '1/2', [R`\frac{5\pi}6 = \pi - \frac\pi6`, R`\sin\frac{5\pi}6 = \sin\frac\pi6 = \frac12`]);
  tableLesson(R`Exact values/\cos`, R`cos: exact values|cos : valeurs exactes|cos: valores exactos|cos の値|cos 的特殊值`,
    { s: R`Cosine runs through the same numbers as sine but backwards: $1, \tfrac{\sqrt3}2, \tfrac{\sqrt2}2, \tfrac12, 0$ for $0, \tfrac\pi6, \tfrac\pi4, \tfrac\pi3, \tfrac\pi2$ — because $\cos x = \sin(\tfrac\pi2 - x)$. Past $\tfrac\pi2$ it turns negative.|Le cosinus parcourt les mêmes nombres que le sinus, à l’envers : $1, \tfrac{\sqrt3}2, \tfrac{\sqrt2}2, \tfrac12, 0$ pour $0, \tfrac\pi6, \tfrac\pi4, \tfrac\pi3, \tfrac\pi2$ — car $\cos x = \sin(\tfrac\pi2 - x)$. Au-delà de $\tfrac\pi2$ il devient négatif.|El coseno recorre los mismos números que el seno, al revés: $1, \tfrac{\sqrt3}2, \tfrac{\sqrt2}2, \tfrac12, 0$ para $0, \tfrac\pi6, \tfrac\pi4, \tfrac\pi3, \tfrac\pi2$, porque $\cos x = \sin(\tfrac\pi2 - x)$. Pasado $\tfrac\pi2$ se vuelve negativo.|cos は sin と同じ数を逆順に：$0, \tfrac\pi6, \tfrac\pi4, \tfrac\pi3, \tfrac\pi2$ で $1, \tfrac{\sqrt3}2, \tfrac{\sqrt2}2, \tfrac12, 0$（$\cos x = \sin(\tfrac\pi2 - x)$ だから）。$\tfrac\pi2$ を過ぎると負。|余弦取的数与正弦相同但顺序相反：$0, \tfrac\pi6, \tfrac\pi4, \tfrac\pi3, \tfrac\pi2$ 时为 $1, \tfrac{\sqrt3}2, \tfrac{\sqrt2}2, \tfrac12, 0$——因为 $\cos x = \sin(\tfrac\pi2 - x)$。过了 $\tfrac\pi2$ 变为负。`,
      a: [F(R`\cos:\ 1,\ \tfrac{\sqrt3}2,\ \tfrac{\sqrt2}2,\ \tfrac12,\ 0`), ...ROW('cos', 'cos(x)').a] },
    R`$\cos\tfrac{3\pi}{4}$: $\tfrac{3\pi}4 = \pi - \tfrac\pi4$ and $\cos(\pi - x) = -\cos x$, so it is $-\tfrac{\sqrt2}2$.|$\cos\tfrac{3\pi}{4}$ : $\tfrac{3\pi}4 = \pi - \tfrac\pi4$ et $\cos(\pi - x) = -\cos x$, donc $-\tfrac{\sqrt2}2$.|$\cos\tfrac{3\pi}{4}$: $\tfrac{3\pi}4 = \pi - \tfrac\pi4$ y $\cos(\pi - x) = -\cos x$, así que es $-\tfrac{\sqrt2}2$.|$\cos\tfrac{3\pi}{4}$：$\cos(\pi - x) = -\cos x$ より $-\tfrac{\sqrt2}2$。|$\cos\tfrac{3\pi}{4}$：$\cos(\pi - x) = -\cos x$，所以为 $-\tfrac{\sqrt2}2$。`,
    [F(R`\cos\frac{3\pi}{4} = -\cos\frac\pi4`), Y(R`= -\frac{\sqrt2}{2}`), AX([-0.3, 3.5], [-1.2, 1.2]), P('y=cos(x)'), PT(3 * PI / 4, -Math.SQRT1_2, R`\tfrac{3\pi}4`)],
    R`Find $\cos\tfrac{5\pi}{4}$.|Calculez $\cos\tfrac{5\pi}{4}$.|Calcula $\cos\tfrac{5\pi}{4}$.|$\cos\tfrac{5\pi}{4}$ を求めよ。|求 $\cos\tfrac{5\pi}{4}$。`, '-sqrt(2)/2', [R`\frac{5\pi}4 = \pi + \frac\pi4`, R`\cos(\pi + x) = -\cos x`, R`\cos\frac{5\pi}4 = -\frac{\sqrt2}{2}`]);
  tableLesson(R`Exact values/\tan`, R`tan: exact values|tan : valeurs exactes|tan: valores exactos|tan の値|tan 的特殊值`,
    { s: R`Divide sine by cosine: $0, \tfrac{1}{\sqrt3} = \tfrac{\sqrt3}3, 1, \sqrt3$, and at $\tfrac\pi2$ the cosine is 0, so the tangent is undefined (vertical asymptote).|On divise le sinus par le cosinus : $0, \tfrac{1}{\sqrt3} = \tfrac{\sqrt3}3, 1, \sqrt3$, et en $\tfrac\pi2$ le cosinus est nul : la tangente n’est pas définie (asymptote verticale).|Divide seno entre coseno: $0, \tfrac{1}{\sqrt3} = \tfrac{\sqrt3}3, 1, \sqrt3$, y en $\tfrac\pi2$ el coseno es 0, así que la tangente no está definida (asíntota vertical).|sin を cos で割る：$0, \tfrac{1}{\sqrt3} = \tfrac{\sqrt3}3, 1, \sqrt3$。$\tfrac\pi2$ では cos = 0 で定義されない（垂直漸近線）。|正弦除以余弦：$0, \tfrac{1}{\sqrt3} = \tfrac{\sqrt3}3, 1, \sqrt3$；在 $\tfrac\pi2$ 处余弦为 0，正切无定义（竖直渐近线）。`,
      a: [F(R`\tan:\ 0,\ \tfrac{\sqrt3}3,\ 1,\ \sqrt3,\ \text{—}`), ...ROW('tan', 'tan(x)').a] },
    R`$\tan\tfrac{5\pi}{4}$: tangent has period $\pi$, so $\tan\tfrac{5\pi}4 = \tan\tfrac\pi4 = 1$.|$\tan\tfrac{5\pi}{4}$ : la tangente est $\pi$-périodique, donc $\tan\tfrac{5\pi}4 = \tan\tfrac\pi4 = 1$.|$\tan\tfrac{5\pi}{4}$: la tangente tiene periodo $\pi$, así que $\tan\tfrac{5\pi}4 = \tan\tfrac\pi4 = 1$.|$\tan\tfrac{5\pi}{4}$：周期 $\pi$ より $\tan\tfrac\pi4 = 1$。|$\tan\tfrac{5\pi}{4}$：周期为 $\pi$，所以 $\tan\tfrac\pi4 = 1$。`,
    [F(R`\tan\frac{5\pi}{4} = \tan\left(\pi + \frac\pi4\right) = \tan\frac\pi4`), Y(R`= 1`)],
    R`Find $\tan\left(-\tfrac{\pi}{3}\right)$.|Calculez $\tan\left(-\tfrac{\pi}{3}\right)$.|Calcula $\tan\left(-\tfrac{\pi}{3}\right)$.|$\tan\left(-\tfrac{\pi}{3}\right)$ を求めよ。|求 $\tan\left(-\tfrac{\pi}{3}\right)$。`, '-sqrt(3)', [R`\tan(-x) = -\tan x`, R`\tan\left(-\frac\pi3\right) = -\sqrt3`]);

  // =============================== Symmetries ===============================
  lesson('Symmetries/Negative angle', 'Negative angles|Angles opposés|Ángulos opuestos|負の角|负角',
    { s: R`Turning clockwise by $x$ gives the mirror image of turning anticlockwise: the point flips across the $x$-axis. Its $x$-coordinate stays (cosine is even), its $y$-coordinate changes sign (sine is odd), and so does the tangent.|Tourner de $x$ dans le sens horaire donne le symétrique du sens trigonométrique : le point se reflète par rapport à l’axe des $x$. L’abscisse reste (le cosinus est pair), l’ordonnée change de signe (le sinus est impair), la tangente aussi.|Girar $x$ en sentido horario da la imagen especular del giro antihorario: el punto se refleja respecto al eje $x$. La coordenada $x$ se mantiene (el coseno es par), la $y$ cambia de signo (el seno es impar), y la tangente también.|時計回りに $x$ 回ると、反時計回りの点を $x$ 軸で折り返した点。$x$ 座標はそのまま（cos は偶関数）、$y$ 座標は符号が変わる（sin は奇関数）、tan も。|顺时针转 $x$ 得到逆时针转 $x$ 的点关于 $x$ 轴的对称点。$x$ 坐标不变（余弦是偶函数），$y$ 坐标变号（正弦是奇函数），正切也变号。`,
      a: [F(R`\cos(-x) = \cos x,\quad \sin(-x) = -\sin x`), F(R`\tan(-x) = -\tan x`), ...UC([['vec', P2(0, 0), P2(Math.cos(0.8), Math.sin(0.8)), { c: 'y' }], ['vec', P2(0, 0), P2(Math.cos(0.8), -Math.sin(0.8)), { c: 'p' }], ['seg', P2(Math.cos(0.8), Math.sin(0.8)), P2(Math.cos(0.8), -Math.sin(0.8)), { c: 'chalk', dash: true }], ['lab3', P2(0.75, 0.8), 'x', { c: 'y' }], ['lab3', P2(0.75, -0.85), '−x', { c: 'p' }]])] },
    { s: R`$\cos(-\tfrac\pi4) = \tfrac{\sqrt2}2$ and $\sin(-\tfrac\pi6) = -\tfrac12$. The graph of cosine is symmetric about the $y$-axis; the graph of sine is symmetric about the origin.|$\cos(-\tfrac\pi4) = \tfrac{\sqrt2}2$ et $\sin(-\tfrac\pi6) = -\tfrac12$. La courbe du cosinus est symétrique par rapport à l’axe des $y$, celle du sinus par rapport à l’origine.|$\cos(-\tfrac\pi4) = \tfrac{\sqrt2}2$ y $\sin(-\tfrac\pi6) = -\tfrac12$. La gráfica del coseno es simétrica respecto al eje $y$; la del seno, respecto al origen.|$\cos(-\tfrac\pi4) = \tfrac{\sqrt2}2$、$\sin(-\tfrac\pi6) = -\tfrac12$。cos のグラフは $y$ 軸対称、sin は原点対称。|$\cos(-\tfrac\pi4) = \tfrac{\sqrt2}2$，$\sin(-\tfrac\pi6) = -\tfrac12$。余弦图像关于 $y$ 轴对称，正弦图像关于原点对称。`,
      a: [F(R`\cos\left(-\tfrac\pi4\right) = \tfrac{\sqrt2}2`), Y(R`\sin\left(-\tfrac\pi6\right) = -\tfrac12`), AX([-3.5, 3.5], [-1.3, 1.3]), P('y=cos(x)', 'b'), P('y=sin(x)', 'y', { d: 300 })] },
    { a: [F(R`\cos\left(-\tfrac\pi3\right) + \sin\left(-\tfrac\pi6\right)`)],
      ex: { k: 'val', v: '0', q: R`Compute $\cos\left(-\tfrac\pi3\right) + \sin\left(-\tfrac\pi6\right)$.|Calculez $\cos\left(-\tfrac\pi3\right) + \sin\left(-\tfrac\pi6\right)$.|Calcula $\cos\left(-\tfrac\pi3\right) + \sin\left(-\tfrac\pi6\right)$.|$\cos\left(-\tfrac\pi3\right) + \sin\left(-\tfrac\pi6\right)$ を計算せよ。|计算 $\cos\left(-\tfrac\pi3\right) + \sin\left(-\tfrac\pi6\right)$。`,
        sol: [R`\cos\left(-\tfrac\pi3\right) = \tfrac12,\quad \sin\left(-\tfrac\pi6\right) = -\tfrac12`, R`\tfrac12 - \tfrac12 = 0`] } });

  lesson('Symmetries/Supplementary angle', 'Supplementary angles|Angles supplémentaires|Ángulos suplementarios|補角|补角',
    { s: R`$\pi - x$ is the mirror of $x$ across the $y$-axis: same height, opposite horizontal position. So the sine is the same and the cosine changes sign. This is why $\sin x = a$ usually has two solutions in $[0, 2\pi)$.|$\pi - x$ est le symétrique de $x$ par rapport à l’axe des $y$ : même hauteur, abscisse opposée. Le sinus reste et le cosinus change de signe. C’est pourquoi $\sin x = a$ a en général deux solutions dans $[0, 2\pi[$.|$\pi - x$ es el simétrico de $x$ respecto al eje $y$: misma altura, posición horizontal opuesta. El seno se mantiene y el coseno cambia de signo. Por eso $\sin x = a$ suele tener dos soluciones en $[0, 2\pi)$.|$\pi - x$ は $x$ を $y$ 軸で折り返した点：高さは同じ、横は逆。sin は同じで cos は符号が変わる。だから $\sin x = a$ は $[0, 2\pi)$ に普通 2 つ解をもつ。|$\pi - x$ 是 $x$ 关于 $y$ 轴的对称点：高度相同，水平位置相反。正弦不变，余弦变号。所以 $\sin x = a$ 在 $[0, 2\pi)$ 内通常有两个解。`,
      a: [F(R`\sin(\pi - x) = \sin x`), F(R`\cos(\pi - x) = -\cos x`), ...UC([['vec', P2(0, 0), P2(Math.cos(0.8), Math.sin(0.8)), { c: 'y' }], ['vec', P2(0, 0), P2(-Math.cos(0.8), Math.sin(0.8)), { c: 'g' }], ['seg', P2(-Math.cos(0.8), Math.sin(0.8)), P2(Math.cos(0.8), Math.sin(0.8)), { c: 'chalk', dash: true }], ['lab3', P2(0.75, 0.85), 'x', { c: 'y' }], ['lab3', P2(-1.05, 0.85), 'π − x', { c: 'g' }]])] },
    { s: R`$\sin 150^\circ = \sin 30^\circ = \tfrac12$ and $\cos 150^\circ = -\cos 30^\circ = -\tfrac{\sqrt3}2$.|$\sin 150^\circ = \sin 30^\circ = \tfrac12$ et $\cos 150^\circ = -\cos 30^\circ = -\tfrac{\sqrt3}2$.|$\sin 150^\circ = \sin 30^\circ = \tfrac12$ y $\cos 150^\circ = -\cos 30^\circ = -\tfrac{\sqrt3}2$.|$\sin 150^\circ = \tfrac12$、$\cos 150^\circ = -\tfrac{\sqrt3}2$。|$\sin 150^\circ = \tfrac12$，$\cos 150^\circ = -\tfrac{\sqrt3}2$。`,
      a: [F(R`\sin 150^\circ = \sin 30^\circ = \tfrac12`), Y(R`\cos 150^\circ = -\cos 30^\circ = -\tfrac{\sqrt3}2`)] },
    { a: [F(R`\cos\tfrac{2\pi}{3}`)],
      ex: { k: 'val', v: '-1/2', q: R`Find $\cos\tfrac{2\pi}{3}$.|Calculez $\cos\tfrac{2\pi}{3}$.|Calcula $\cos\tfrac{2\pi}{3}$.|$\cos\tfrac{2\pi}{3}$ を求めよ。|求 $\cos\tfrac{2\pi}{3}$。`,
        sol: [R`\frac{2\pi}3 = \pi - \frac\pi3`, R`\cos\frac{2\pi}3 = -\cos\frac\pi3 = -\frac12`] } });

  lesson('Symmetries/Half turn', 'Half turn|Demi-tour|Media vuelta|半回転|转半圈',
    { s: R`Adding $\pi$ sends the point to the opposite side of the circle: both coordinates change sign. Sine and cosine flip, but their quotient, the tangent, stays the same — that is why tangent has period $\pi$.|Ajouter $\pi$ envoie le point à l’opposé sur le cercle : les deux coordonnées changent de signe. Sinus et cosinus changent de signe, mais leur quotient, la tangente, reste le même — d’où sa période $\pi$.|Sumar $\pi$ lleva el punto al lado opuesto de la circunferencia: las dos coordenadas cambian de signo. Seno y coseno cambian, pero su cociente, la tangente, se mantiene: por eso su periodo es $\pi$.|$\pi$ を足すと円の反対側へ：両方の座標の符号が変わる。sin と cos は符号が変わるが、比の tan は同じ。だから tan の周期は $\pi$。|加上 $\pi$ 把点送到圆的另一侧：两个坐标都变号。正弦、余弦变号，但其商正切不变——这就是正切周期为 $\pi$ 的原因。`,
      a: [F(R`\sin(x + \pi) = -\sin x,\quad \cos(x + \pi) = -\cos x`), Y(R`\tan(x + \pi) = \tan x`), ...UC([['vec', P2(0, 0), P2(Math.cos(0.8), Math.sin(0.8)), { c: 'y' }], ['vec', P2(0, 0), P2(-Math.cos(0.8), -Math.sin(0.8)), { c: 'p' }], ['lab3', P2(0.75, 0.85), 'x', { c: 'y' }], ['lab3', P2(-0.9, -0.9), 'x + π', { c: 'p' }]])] },
    { s: R`$\sin\tfrac{4\pi}{3} = \sin(\tfrac\pi3 + \pi) = -\tfrac{\sqrt3}2$ and $\tan\tfrac{4\pi}3 = \tan\tfrac\pi3 = \sqrt3$.|$\sin\tfrac{4\pi}{3} = \sin(\tfrac\pi3 + \pi) = -\tfrac{\sqrt3}2$ et $\tan\tfrac{4\pi}3 = \tan\tfrac\pi3 = \sqrt3$.|$\sin\tfrac{4\pi}{3} = \sin(\tfrac\pi3 + \pi) = -\tfrac{\sqrt3}2$ y $\tan\tfrac{4\pi}3 = \tan\tfrac\pi3 = \sqrt3$.|$\sin\tfrac{4\pi}{3} = -\tfrac{\sqrt3}2$、$\tan\tfrac{4\pi}3 = \sqrt3$。|$\sin\tfrac{4\pi}{3} = -\tfrac{\sqrt3}2$，$\tan\tfrac{4\pi}3 = \sqrt3$。`,
      a: [F(R`\sin\tfrac{4\pi}3 = -\sin\tfrac\pi3 = -\tfrac{\sqrt3}2`), Y(R`\tan\tfrac{4\pi}3 = \tan\tfrac\pi3 = \sqrt3`)] },
    { a: [F(R`\sin\tfrac{7\pi}{6}`)],
      ex: { k: 'val', v: '-1/2', q: R`Find $\sin\tfrac{7\pi}{6}$.|Calculez $\sin\tfrac{7\pi}{6}$.|Calcula $\sin\tfrac{7\pi}{6}$.|$\sin\tfrac{7\pi}{6}$ を求めよ。|求 $\sin\tfrac{7\pi}{6}$。`,
        sol: [R`\frac{7\pi}6 = \frac\pi6 + \pi`, R`\sin\frac{7\pi}6 = -\sin\frac\pi6 = -\frac12`] } });

  lesson('Symmetries/Quarter turn', 'Quarter turn|Quart de tour|Cuarto de vuelta|4 分の 1 回転|转四分之一圈',
    { s: R`Shifting by $\tfrac\pi2$ turns the radius a quarter turn, which swaps the roles of the coordinates. On the graphs: the sine curve shifted left by $\tfrac\pi2$ is exactly the cosine curve.|Décaler de $\tfrac\pi2$ fait tourner le rayon d’un quart de tour, ce qui échange les rôles des coordonnées. Sur les courbes : la sinusoïde décalée de $\tfrac\pi2$ vers la gauche est exactement la courbe du cosinus.|Desplazar $\tfrac\pi2$ gira el radio un cuarto de vuelta, lo que intercambia los papeles de las coordenadas. En las gráficas: la curva del seno desplazada $\tfrac\pi2$ a la izquierda es exactamente la del coseno.|$\tfrac\pi2$ ずらすと半径が 4 分の 1 回転し、座標の役割が入れ替わる。グラフでは sin を左に $\tfrac\pi2$ ずらすとちょうど cos。|平移 $\tfrac\pi2$ 让半径转四分之一圈，两个坐标的角色互换。图像上：正弦曲线左移 $\tfrac\pi2$ 正好是余弦曲线。`,
      a: [F(R`\sin\left(x + \tfrac\pi2\right) = \cos x`), F(R`\cos\left(x + \tfrac\pi2\right) = -\sin x`), AX([-3.6, 4], [-1.3, 1.3]), P('y=sin(x)', 'b'), P('y=sin(x+pi/2)', 'y', { d: 400 })] },
    { s: R`$\sin(x + \tfrac\pi2) + \sin(x - \tfrac\pi2) = \cos x - \cos x = 0$, since $\sin(x - \tfrac\pi2) = -\cos x$.|$\sin(x + \tfrac\pi2) + \sin(x - \tfrac\pi2) = \cos x - \cos x = 0$, car $\sin(x - \tfrac\pi2) = -\cos x$.|$\sin(x + \tfrac\pi2) + \sin(x - \tfrac\pi2) = \cos x - \cos x = 0$, ya que $\sin(x - \tfrac\pi2) = -\cos x$.|$\sin(x - \tfrac\pi2) = -\cos x$ より $\sin(x + \tfrac\pi2) + \sin(x - \tfrac\pi2) = 0$。|因 $\sin(x - \tfrac\pi2) = -\cos x$，所以 $\sin(x + \tfrac\pi2) + \sin(x - \tfrac\pi2) = 0$。`,
      a: [F(R`\sin\left(x - \tfrac\pi2\right) = -\cos x`), Y(R`\sin\left(x + \tfrac\pi2\right) + \sin\left(x - \tfrac\pi2\right) = 0`)] },
    { a: [F(R`\sin\left(x + \tfrac\pi2\right) + \cos\left(x + \tfrac\pi2\right)`)],
      ex: { k: 'expr', f: 'sin(x+pi/2)+cos(x+pi/2)', ans: 'cos(x)-sin(x)', q: R`Simplify $\sin\left(x + \tfrac\pi2\right) + \cos\left(x + \tfrac\pi2\right)$ in terms of $\sin x$ and $\cos x$.|Simplifiez $\sin\left(x + \tfrac\pi2\right) + \cos\left(x + \tfrac\pi2\right)$ en fonction de $\sin x$ et $\cos x$.|Simplifica $\sin\left(x + \tfrac\pi2\right) + \cos\left(x + \tfrac\pi2\right)$ en función de $\sin x$ y $\cos x$.|$\sin\left(x + \tfrac\pi2\right) + \cos\left(x + \tfrac\pi2\right)$ を $\sin x$, $\cos x$ で表せ。|用 $\sin x$、$\cos x$化简 $\sin\left(x + \tfrac\pi2\right) + \cos\left(x + \tfrac\pi2\right)$。`,
        sol: [R`\sin\left(x + \tfrac\pi2\right) = \cos x`, R`\cos\left(x + \tfrac\pi2\right) = -\sin x`, R`= \cos x - \sin x`] } });

  // =============================== Sum and difference ===============================
  const SA = R`$\sin a = \tfrac35$, $\cos b = \tfrac5{13}$, $a, b$ acute|$\sin a = \tfrac35$, $\cos b = \tfrac5{13}$, $a, b$ aigus|$\sin a = \tfrac35$, $\cos b = \tfrac5{13}$, $a, b$ agudos|$\sin a = \tfrac35$, $\cos b = \tfrac5{13}$（$a, b$ は鋭角）|$\sin a = \tfrac35$，$\cos b = \tfrac5{13}$，$a, b$ 为锐角`.split('|');
  lesson('Sum and difference/Sine', 'Sine of a sum|Sinus d’une somme|Seno de una suma|sin の加法定理|正弦和角公式',
    { s: R`The sine of a sum is not the sum of sines. It mixes both functions: “sine-cosine plus cosine-sine”, with the same sign as in $a \pm b$. Typical use: new exact values ($75^\circ = 45^\circ + 30^\circ$) or combining two known angles.|Le sinus d’une somme n’est pas la somme des sinus. Il mélange les deux fonctions : « sinus-cosinus plus cosinus-sinus », avec le même signe que dans $a \pm b$. Usage : nouvelles valeurs exactes ($75^\circ = 45^\circ + 30^\circ$) ou combinaison de deux angles connus.|El seno de una suma no es la suma de senos. Mezcla las dos funciones: «seno-coseno más coseno-seno», con el mismo signo que en $a \pm b$. Uso típico: valores exactos nuevos ($75^\circ = 45^\circ + 30^\circ$) o combinar dos ángulos conocidos.|和の sin は sin の和ではない。「sin·cos + cos·sin」と両方が混ざり、符号は $a \pm b$ と同じ。新しい厳密値（$75^\circ = 45^\circ + 30^\circ$）や 2 つの角の合成に使う。|和角的正弦不等于正弦之和。它混合两种函数：“正余加余正”，符号与 $a \pm b$ 相同。典型用途：新的精确值（$75^\circ = 45^\circ + 30^\circ$）或合并两个已知角。`,
      a: [Y(R`\sin(a \pm b) = \sin a\cos b \pm \cos a\sin b`), W('sin(a + b) ≠ sin a + sin b|sin(a + b) ≠ sin a + sin b|sin(a + b) ≠ sin a + sin b|sin(a + b) ≠ sin a + sin b|sin(a + b) ≠ sin a + sin b', { c: 'p' })] },
    { s: R`$\sin 75^\circ = \sin 45^\circ\cos 30^\circ + \cos 45^\circ\sin 30^\circ = \tfrac{\sqrt2}2\cdot\tfrac{\sqrt3}2 + \tfrac{\sqrt2}2\cdot\tfrac12 = \tfrac{\sqrt6 + \sqrt2}4$.|$\sin 75^\circ = \sin 45^\circ\cos 30^\circ + \cos 45^\circ\sin 30^\circ = \tfrac{\sqrt6 + \sqrt2}4$.|$\sin 75^\circ = \sin 45^\circ\cos 30^\circ + \cos 45^\circ\sin 30^\circ = \tfrac{\sqrt6 + \sqrt2}4$.|$\sin 75^\circ = \sin 45^\circ\cos 30^\circ + \cos 45^\circ\sin 30^\circ = \tfrac{\sqrt6 + \sqrt2}4$。|$\sin 75^\circ = \sin 45^\circ\cos 30^\circ + \cos 45^\circ\sin 30^\circ = \tfrac{\sqrt6 + \sqrt2}4$。`,
      a: [F(R`\sin(45^\circ + 30^\circ) = \tfrac{\sqrt2}2\cdot\tfrac{\sqrt3}2 + \tfrac{\sqrt2}2\cdot\tfrac12`), Y(R`= \frac{\sqrt6 + \sqrt2}{4}`)] },
    { a: [F(R`\sin a = \tfrac35,\quad \cos b = \tfrac5{13}`)],
      ex: { k: 'val', v: '63/65', q: `${SA[0]}. Find $\\sin(a + b)$.|${SA[1]}. Calculez $\\sin(a + b)$.|${SA[2]}. Calcula $\\sin(a + b)$.|${SA[3]}。$\\sin(a + b)$ を求めよ。|${SA[4]}，求 $\\sin(a + b)$。`,
        sol: [R`\cos a = \tfrac45,\quad \sin b = \tfrac{12}{13}`, R`\sin(a + b) = \tfrac35\cdot\tfrac5{13} + \tfrac45\cdot\tfrac{12}{13}`, R`= \tfrac{15 + 48}{65} = \tfrac{63}{65}`] } });

  lesson('Sum and difference/Cosine', 'Cosine of a sum|Cosinus d’une somme|Coseno de una suma|cos の加法定理|余弦和角公式',
    { s: R`For cosine the products pair like with like — “cosine-cosine, sine-sine” — and the sign is the opposite of the one in $a \pm b$. Setting $a = b$ gives the double-angle formula.|Pour le cosinus on associe les mêmes fonctions — « cosinus-cosinus, sinus-sinus » — et le signe est l’inverse de celui de $a \pm b$. Avec $a = b$ on obtient la formule de duplication.|En el coseno se emparejan iguales —«coseno-coseno, seno-seno»— y el signo es el contrario al de $a \pm b$. Con $a = b$ sale la fórmula del ángulo doble.|cos では同じもの同士「cos·cos、sin·sin」を掛け、符号は $a \pm b$ と逆。$a = b$ とすると 2 倍角の公式。|余弦公式同类相乘——“余余、正正”——符号与 $a \pm b$ 相反。令 $a = b$ 得二倍角公式。`,
      a: [Y(R`\cos(a \pm b) = \cos a\cos b \mp \sin a\sin b`), W('opposite sign!|signe inversé !|¡signo contrario!|符号は逆！|符号相反！', { c: 'p' })] },
    { s: R`$\cos 15^\circ = \cos(45^\circ - 30^\circ) = \cos 45^\circ\cos 30^\circ + \sin 45^\circ\sin 30^\circ = \tfrac{\sqrt6 + \sqrt2}{4}$: the minus inside became a plus.|$\cos 15^\circ = \cos(45^\circ - 30^\circ) = \cos 45^\circ\cos 30^\circ + \sin 45^\circ\sin 30^\circ = \tfrac{\sqrt6 + \sqrt2}{4}$ : le moins est devenu un plus.|$\cos 15^\circ = \cos(45^\circ - 30^\circ) = \cos 45^\circ\cos 30^\circ + \sin 45^\circ\sin 30^\circ = \tfrac{\sqrt6 + \sqrt2}{4}$: el menos se convirtió en más.|$\cos 15^\circ = \cos(45^\circ - 30^\circ) = \cos 45^\circ\cos 30^\circ + \sin 45^\circ\sin 30^\circ = \tfrac{\sqrt6 + \sqrt2}{4}$（マイナスがプラスに）。|$\cos 15^\circ = \cos(45^\circ - 30^\circ) = \cos 45^\circ\cos 30^\circ + \sin 45^\circ\sin 30^\circ = \tfrac{\sqrt6 + \sqrt2}{4}$：减号变成了加号。`,
      a: [F(R`\cos(45^\circ - 30^\circ) = \cos 45^\circ\cos 30^\circ + \sin 45^\circ\sin 30^\circ`, { s: 22 }), Y(R`= \frac{\sqrt6 + \sqrt2}{4}`)] },
    { a: [F(R`\sin a = \tfrac35,\quad \cos b = \tfrac5{13}`)],
      ex: { k: 'val', v: '56/65', q: `${SA[0]}. Find $\\cos(a - b)$.|${SA[1]}. Calculez $\\cos(a - b)$.|${SA[2]}. Calcula $\\cos(a - b)$.|${SA[3]}。$\\cos(a - b)$ を求めよ。|${SA[4]}，求 $\\cos(a - b)$。`,
        sol: [R`\cos a = \tfrac45,\quad \sin b = \tfrac{12}{13}`, R`\cos(a - b) = \tfrac45\cdot\tfrac5{13} + \tfrac35\cdot\tfrac{12}{13}`, R`= \tfrac{20 + 36}{65} = \tfrac{56}{65}`] } });

  lesson('Sum and difference/Tangent', 'Tangent of a sum|Tangente d’une somme|Tangente de una suma|tan の加法定理|正切和角公式',
    { s: R`Divide the sine formula by the cosine formula and then divide top and bottom by $\cos a\cos b$: only tangents remain. Useful when you know tangents (slopes!) — the angle between two lines comes from this formula.|On divise la formule du sinus par celle du cosinus, puis haut et bas par $\cos a\cos b$ : il ne reste que des tangentes. Utile quand on connaît des tangentes (des pentes !) — l’angle de deux droites vient de cette formule.|Divide la fórmula del seno entre la del coseno y luego numerador y denominador entre $\cos a\cos b$: solo quedan tangentes. Útil cuando conoces tangentes (¡pendientes!): el ángulo entre dos rectas sale de aquí.|sin の公式を cos の公式で割り、分子分母を $\cos a\cos b$ で割ると tan だけが残る。tan（傾き）がわかっているとき便利で、2 直線のなす角もこの公式から。|用正弦公式除以余弦公式，再分子分母同除 $\cos a\cos b$：只剩正切。已知正切（斜率！）时很有用——两直线夹角就来自这个公式。`,
      a: [Y(R`\tan(a \pm b) = \frac{\tan a \pm \tan b}{1 \mp \tan a\tan b}`)] },
    { s: R`$\tan 75^\circ = \tan(45^\circ + 30^\circ) = \dfrac{1 + \tfrac{1}{\sqrt3}}{1 - \tfrac{1}{\sqrt3}} = \dfrac{\sqrt3 + 1}{\sqrt3 - 1} = 2 + \sqrt3$.|$\tan 75^\circ = \tan(45^\circ + 30^\circ) = \dfrac{1 + \tfrac{1}{\sqrt3}}{1 - \tfrac{1}{\sqrt3}} = 2 + \sqrt3$.|$\tan 75^\circ = \tan(45^\circ + 30^\circ) = \dfrac{1 + \tfrac{1}{\sqrt3}}{1 - \tfrac{1}{\sqrt3}} = 2 + \sqrt3$.|$\tan 75^\circ = \dfrac{1 + \tfrac{1}{\sqrt3}}{1 - \tfrac{1}{\sqrt3}} = 2 + \sqrt3$。|$\tan 75^\circ = \dfrac{1 + \tfrac{1}{\sqrt3}}{1 - \tfrac{1}{\sqrt3}} = 2 + \sqrt3$。`,
      a: [F(R`\tan 75^\circ = \frac{1 + \tfrac{1}{\sqrt3}}{1 - \tfrac{1}{\sqrt3}} = \frac{\sqrt3 + 1}{\sqrt3 - 1}`), Y(R`= 2 + \sqrt3`)] },
    { a: [F(R`\tan a = \tfrac12,\quad \tan b = \tfrac13`)],
      ex: { k: 'val', v: '1', q: R`If $\tan a = \tfrac12$ and $\tan b = \tfrac13$, find $\tan(a + b)$.|Si $\tan a = \tfrac12$ et $\tan b = \tfrac13$, calculez $\tan(a + b)$.|Si $\tan a = \tfrac12$ y $\tan b = \tfrac13$, calcula $\tan(a + b)$.|$\tan a = \tfrac12$, $\tan b = \tfrac13$ のとき $\tan(a + b)$ を求めよ。|若 $\tan a = \tfrac12$，$\tan b = \tfrac13$，求 $\tan(a + b)$。`,
        sol: [R`\frac{\tfrac12 + \tfrac13}{1 - \tfrac12\cdot\tfrac13} = \frac{5/6}{5/6}`, R`= 1\quad (a + b = \tfrac\pi4)`] } });

  // =============================== Double and half angles ===============================
  lesson('Double and half angles/Double angle', 'Double angle|Angle double|Ángulo doble|2 倍角の公式|二倍角公式',
    { s: R`Put $b = a$ in the addition formulas. $\sin 2x = 2\sin x\cos x$ — not $2\sin x$: the graph of $\sin 2x$ is squeezed horizontally, not stretched vertically.|On pose $b = a$ dans les formules d’addition. $\sin 2x = 2\sin x\cos x$ — et non $2\sin x$ : la courbe de $\sin 2x$ est comprimée horizontalement, pas étirée verticalement.|Haz $b = a$ en las fórmulas de la suma. $\sin 2x = 2\sin x\cos x$, no $2\sin x$: la gráfica de $\sin 2x$ se comprime en horizontal, no se estira en vertical.|加法定理で $b = a$ とおく。$\sin 2x = 2\sin x\cos x$（$2\sin x$ ではない）：$\sin 2x$ のグラフは横に縮み、縦には伸びない。|在和角公式中令 $b = a$。$\sin 2x = 2\sin x\cos x$——不是 $2\sin x$：$\sin 2x$ 的图像是水平压缩，不是竖直拉伸。`,
      a: [Y(R`\sin 2x = 2\sin x\cos x`), F(R`\tan 2x = \frac{2\tan x}{1 - \tan^2 x}`), AX([-0.3, 6.6], [-2.2, 2.2]), P('y=sin(2x)'), P('y=2sin(x)', 'p', { d: 300, dash: true }), LBL(0.5, -1.4, R`\sin 2x`), LBL(4.6, -1.9, R`2\sin x`, 'p')] },
    { s: R`$\sin x = \tfrac35$ with $x$ acute: $\cos x = \tfrac45$, so $\sin 2x = 2\cdot\tfrac35\cdot\tfrac45 = \tfrac{24}{25}$.|$\sin x = \tfrac35$ avec $x$ aigu : $\cos x = \tfrac45$, donc $\sin 2x = 2\cdot\tfrac35\cdot\tfrac45 = \tfrac{24}{25}$.|$\sin x = \tfrac35$ con $x$ agudo: $\cos x = \tfrac45$, así que $\sin 2x = 2\cdot\tfrac35\cdot\tfrac45 = \tfrac{24}{25}$.|$\sin x = \tfrac35$（鋭角）：$\cos x = \tfrac45$ で $\sin 2x = \tfrac{24}{25}$。|$\sin x = \tfrac35$，$x$ 为锐角：$\cos x = \tfrac45$，$\sin 2x = \tfrac{24}{25}$。`,
      a: [F(R`\cos x = \tfrac45`), Y(R`\sin 2x = 2\cdot\tfrac35\cdot\tfrac45 = \tfrac{24}{25}`)] },
    { a: [F(R`\tan x = 2`)],
      ex: { k: 'val', v: '-4/3', q: R`If $\tan x = 2$, find $\tan 2x$.|Si $\tan x = 2$, calculez $\tan 2x$.|Si $\tan x = 2$, calcula $\tan 2x$.|$\tan x = 2$ のとき $\tan 2x$ を求めよ。|若 $\tan x = 2$，求 $\tan 2x$。`,
        sol: [R`\tan 2x = \frac{2\cdot 2}{1 - 2^2}`, R`= \frac{4}{-3} = -\frac43`] } });

  lesson('Double and half angles/Cosine of a double angle', 'Cosine of a double angle|Cosinus de l’angle double|Coseno del ángulo doble|cos の 2 倍角|余弦二倍角',
    { s: R`$\cos 2x = \cos^2 x - \sin^2 x$, and replacing one square with $\sin^2 + \cos^2 = 1$ gives two more versions. Choose the one that uses what you know: only $\cos x$, only $\sin x$, or both.|$\cos 2x = \cos^2 x - \sin^2 x$, et en remplaçant un carré grâce à $\sin^2 + \cos^2 = 1$ on obtient deux autres versions. On choisit celle qui utilise ce que l’on connaît : seulement $\cos x$, seulement $\sin x$, ou les deux.|$\cos 2x = \cos^2 x - \sin^2 x$, y sustituyendo un cuadrado con $\sin^2 + \cos^2 = 1$ salen otras dos versiones. Elige la que use lo que conoces: solo $\cos x$, solo $\sin x$ o ambos.|$\cos 2x = \cos^2 x - \sin^2 x$。$\sin^2 + \cos^2 = 1$ で一方を置き換えると 2 つの別形。$\cos x$ だけ、$\sin x$ だけ、両方、のうちわかっているものに合わせて選ぶ。|$\cos 2x = \cos^2 x - \sin^2 x$，用 $\sin^2 + \cos^2 = 1$ 替换一个平方又得两种形式。按已知选用：只知 $\cos x$、只知 $\sin x$ 或两者都知。`,
      a: [F(R`\cos 2x = \cos^2 x - \sin^2 x`), Y(R`= 2\cos^2 x - 1 = 1 - 2\sin^2 x`), W('pick the version that uses what you know|choisir la version adaptée aux données|elige la versión según los datos|わかっているものに合わせて選ぶ|按已知条件选形式')] },
    { s: R`If $\sin x = \tfrac13$: $\cos 2x = 1 - 2\cdot\tfrac19 = \tfrac79$ — no need to find $\cos x$ at all.|Si $\sin x = \tfrac13$ : $\cos 2x = 1 - 2\cdot\tfrac19 = \tfrac79$ — inutile de calculer $\cos x$.|Si $\sin x = \tfrac13$: $\cos 2x = 1 - 2\cdot\tfrac19 = \tfrac79$, sin necesidad de hallar $\cos x$.|$\sin x = \tfrac13$ なら $\cos 2x = 1 - 2\cdot\tfrac19 = \tfrac79$（$\cos x$ は不要）。|若 $\sin x = \tfrac13$：$\cos 2x = 1 - 2\cdot\tfrac19 = \tfrac79$——根本不用求 $\cos x$。`,
      a: [F(R`\sin x = \tfrac13`), Y(R`\cos 2x = 1 - 2\sin^2 x = 1 - \tfrac29 = \tfrac79`)] },
    { a: [F(R`\cos x = \tfrac13`)],
      ex: { k: 'val', v: '-7/9', q: R`If $\cos x = \tfrac13$, find $\cos 2x$.|Si $\cos x = \tfrac13$, calculez $\cos 2x$.|Si $\cos x = \tfrac13$, calcula $\cos 2x$.|$\cos x = \tfrac13$ のとき $\cos 2x$ を求めよ。|若 $\cos x = \tfrac13$，求 $\cos 2x$。`,
        sol: [R`\cos 2x = 2\cos^2 x - 1`, R`= 2\cdot\tfrac19 - 1 = -\tfrac79`] } });

  lesson('Double and half angles/Lowering the power', 'Lowering the power|Linéarisation|Reducción de potencias|次数下げ|降幂公式',
    { s: R`Solve the double-angle formula for $\sin^2 x$ or $\cos^2 x$: a square becomes a first power of $\cos 2x$. This is how you integrate $\sin^2 x$, and how you find half-angle values like $\cos\tfrac\pi8$.|On résout la formule de duplication en $\sin^2 x$ ou $\cos^2 x$ : un carré devient une puissance 1 de $\cos 2x$. C’est ainsi qu’on intègre $\sin^2 x$, et qu’on trouve des valeurs d’angle moitié comme $\cos\tfrac\pi8$.|Despeja $\sin^2 x$ o $\cos^2 x$ de la fórmula del ángulo doble: un cuadrado pasa a ser una potencia 1 de $\cos 2x$. Así se integra $\sin^2 x$ y se hallan valores del ángulo mitad como $\cos\tfrac\pi8$.|2 倍角の公式を $\sin^2 x$ や $\cos^2 x$ について解くと、2 乗が $\cos 2x$ の 1 次に。$\sin^2 x$ の積分や $\cos\tfrac\pi8$ のような半角の値に使う。|由二倍角公式解出 $\sin^2 x$ 或 $\cos^2 x$：平方变成 $\cos 2x$ 的一次式。积分 $\sin^2 x$、求 $\cos\tfrac\pi8$ 这样的半角值都用它。`,
      a: [Y(R`\sin^2 x = \frac{1 - \cos 2x}{2},\quad \cos^2 x = \frac{1 + \cos 2x}{2}`, { s: 24 }), AX([-0.3, 6.6], [-0.3, 1.3]), P('y=sin(x)^2'), P('y=(1-cos(2x))/2', 'b', { d: 400, dash: true })] },
    { s: R`$\sin^2\tfrac\pi{12} = \dfrac{1 - \cos\tfrac\pi6}{2} = \dfrac{1 - \tfrac{\sqrt3}2}{2} = \dfrac{2 - \sqrt3}{4}$.|$\sin^2\tfrac\pi{12} = \dfrac{1 - \cos\tfrac\pi6}{2} = \dfrac{2 - \sqrt3}{4}$.|$\sin^2\tfrac\pi{12} = \dfrac{1 - \cos\tfrac\pi6}{2} = \dfrac{2 - \sqrt3}{4}$.|$\sin^2\tfrac\pi{12} = \dfrac{1 - \cos\tfrac\pi6}{2} = \dfrac{2 - \sqrt3}{4}$。|$\sin^2\tfrac\pi{12} = \dfrac{1 - \cos\tfrac\pi6}{2} = \dfrac{2 - \sqrt3}{4}$。`,
      a: [F(R`\sin^2\frac\pi{12} = \frac{1 - \cos\tfrac\pi6}{2}`), Y(R`= \frac{2 - \sqrt3}{4}`)] },
    { a: [F(R`\cos^2\tfrac\pi8`)],
      ex: { k: 'val', v: '(2+sqrt(2))/4', q: R`Find the exact value of $\cos^2\tfrac\pi8$.|Donnez la valeur exacte de $\cos^2\tfrac\pi8$.|Halla el valor exacto de $\cos^2\tfrac\pi8$.|$\cos^2\tfrac\pi8$ の厳密な値を求めよ。|求 $\cos^2\tfrac\pi8$ 的精确值。`,
        sol: [R`\cos^2\frac\pi8 = \frac{1 + \cos\tfrac\pi4}{2}`, R`= \frac{1 + \tfrac{\sqrt2}2}{2} = \frac{2 + \sqrt2}{4}`] } });

  lesson('Double and half angles/Triple angle', 'Triple angle|Angle triple|Ángulo triple|3 倍角の公式|三倍角公式',
    { s: R`Write $3x = 2x + x$, use the addition formula, then the double-angle formulas and $\cos^2 = 1 - \sin^2$. The result depends on $\sin x$ alone (or $\cos x$ alone): a cubic.|On écrit $3x = 2x + x$, on applique la formule d’addition, puis celles de l’angle double et $\cos^2 = 1 - \sin^2$. Le résultat ne dépend que de $\sin x$ (ou que de $\cos x$) : un polynôme de degré 3.|Escribe $3x = 2x + x$, aplica la fórmula de la suma, luego las del ángulo doble y $\cos^2 = 1 - \sin^2$. El resultado depende solo de $\sin x$ (o solo de $\cos x$): un polinomio cúbico.|$3x = 2x + x$ と書き、加法定理、2 倍角、$\cos^2 = 1 - \sin^2$ を使うと、$\sin x$ だけ（または $\cos x$ だけ）の 3 次式になる。|写 $3x = 2x + x$，用和角公式，再用二倍角公式和 $\cos^2 = 1 - \sin^2$。结果只含 $\sin x$（或只含 $\cos x$）：三次式。`,
      a: [F(R`\sin 3x = 3\sin x - 4\sin^3 x`), F(R`\cos 3x = 4\cos^3 x - 3\cos x`), W('from 3x = 2x + x|à partir de 3x = 2x + x|a partir de 3x = 2x + x|3x = 2x + x から|由 3x = 2x + x')] },
    { s: R`Check with $x = 60^\circ$: $\cos x = \tfrac12$, so $\cos 3x = 4\cdot\tfrac18 - \tfrac32 = -1$, and indeed $\cos 180^\circ = -1$.|Vérification avec $x = 60^\circ$ : $\cos x = \tfrac12$, donc $\cos 3x = 4\cdot\tfrac18 - \tfrac32 = -1$, et en effet $\cos 180^\circ = -1$.|Comprobación con $x = 60^\circ$: $\cos x = \tfrac12$, así que $\cos 3x = 4\cdot\tfrac18 - \tfrac32 = -1$, y en efecto $\cos 180^\circ = -1$.|$x = 60^\circ$ で確認：$\cos 3x = 4\cdot\tfrac18 - \tfrac32 = -1 = \cos 180^\circ$。|用 $x = 60^\circ$ 验证：$\cos 3x = 4\cdot\tfrac18 - \tfrac32 = -1 = \cos 180^\circ$。`,
      a: [F(R`\cos x = \tfrac12:\ 4\cdot\tfrac18 - 3\cdot\tfrac12`), Y(R`= -1 = \cos 180^\circ\ \checkmark`)] },
    { a: [F(R`\sin x = \tfrac12`)],
      ex: { k: 'val', v: '1', q: R`If $\sin x = \tfrac12$, use the triple-angle formula to find $\sin 3x$.|Si $\sin x = \tfrac12$, calculez $\sin 3x$ avec la formule de l’angle triple.|Si $\sin x = \tfrac12$, usa la fórmula del ángulo triple para hallar $\sin 3x$.|$\sin x = \tfrac12$ のとき 3 倍角の公式で $\sin 3x$ を求めよ。|若 $\sin x = \tfrac12$，用三倍角公式求 $\sin 3x$。`,
        sol: [R`\sin 3x = 3\cdot\tfrac12 - 4\cdot\tfrac18`, R`= \tfrac32 - \tfrac12 = 1`] } });

  lesson('Double and half angles/In terms of t = tan(x/2)', 'The t = tan(x/2) substitution|La substitution t = tan(x/2)|El cambio t = tan(x/2)|t = tan(x/2) の置換|万能代换 t = tan(x/2)',
    { s: R`With $t = \tan\tfrac x2$, sine, cosine and tangent of $x$ become fractions in $t$. It turns any trigonometric equation or integral in $\sin x$, $\cos x$ into an algebraic one.|Avec $t = \tan\tfrac x2$, sinus, cosinus et tangente de $x$ deviennent des fractions en $t$. Toute équation ou intégrale trigonométrique en $\sin x$, $\cos x$ devient algébrique.|Con $t = \tan\tfrac x2$, seno, coseno y tangente de $x$ pasan a ser fracciones en $t$. Así cualquier ecuación o integral en $\sin x$, $\cos x$ se vuelve algebraica.|$t = \tan\tfrac x2$ とおくと、$x$ の sin, cos, tan が $t$ の分数式になり、三角方程式や積分が代数的なものになる。|令 $t = \tan\tfrac x2$，$x$ 的正弦、余弦、正切都变成 $t$ 的分式。任何含 $\sin x$、$\cos x$ 的方程或积分都化为代数问题。`,
      a: [Y(R`\sin x = \frac{2t}{1 + t^2},\quad \cos x = \frac{1 - t^2}{1 + t^2}`, { s: 24 }), F(R`\tan x = \frac{2t}{1 - t^2}`)] },
    { s: R`$t = 1$ means $\tfrac x2 = \tfrac\pi4$, so $x = \tfrac\pi2$: the formulas give $\sin x = \tfrac22 = 1$ and $\cos x = 0$, as they should.|$t = 1$ signifie $\tfrac x2 = \tfrac\pi4$, donc $x = \tfrac\pi2$ : les formules donnent $\sin x = \tfrac22 = 1$ et $\cos x = 0$, comme prévu.|$t = 1$ significa $\tfrac x2 = \tfrac\pi4$, así que $x = \tfrac\pi2$: las fórmulas dan $\sin x = \tfrac22 = 1$ y $\cos x = 0$, como debe ser.|$t = 1$ なら $x = \tfrac\pi2$：公式は $\sin x = 1$, $\cos x = 0$ を与える。|$t = 1$ 即 $x = \tfrac\pi2$：公式给出 $\sin x = 1$，$\cos x = 0$，正确。`,
      a: [F(R`t = 1:\ \sin x = \frac{2}{2} = 1,\ \cos x = \frac{0}{2} = 0`), Y(R`x = \frac\pi2\ \checkmark`)] },
    { a: [F(R`\tan\tfrac x2 = \tfrac12`)],
      ex: { k: 'val', v: '4/5', q: R`If $\tan\tfrac x2 = \tfrac12$, find $\sin x$.|Si $\tan\tfrac x2 = \tfrac12$, calculez $\sin x$.|Si $\tan\tfrac x2 = \tfrac12$, halla $\sin x$.|$\tan\tfrac x2 = \tfrac12$ のとき $\sin x$ を求めよ。|若 $\tan\tfrac x2 = \tfrac12$，求 $\sin x$。`,
        sol: [R`\sin x = \frac{2\cdot\tfrac12}{1 + \tfrac14}`, R`= \frac{1}{5/4} = \frac45`] } });

  // =============================== Sums and products ===============================
  lesson('Sums and products/Sum to product', 'Sum to product|Somme en produit|Suma a producto|和積公式|和差化积',
    { s: R`A sum of two sines becomes a product: twice the sine of the average times the cosine of the half-difference. Products are what you want when solving equations ($A\cdot B = 0$ splits into two easy cases).|Une somme de deux sinus devient un produit : deux fois le sinus de la moyenne par le cosinus de la demi-différence. Un produit est ce qu’il faut pour résoudre une équation ($A\cdot B = 0$ se scinde en deux cas simples).|Una suma de dos senos se convierte en un producto: dos veces el seno de la media por el coseno de la semidiferencia. Los productos son lo que conviene para resolver ecuaciones ($A\cdot B = 0$ se separa en dos casos fáciles).|2 つの sin の和は積になる：平均の sin × 半差の cos × 2。方程式では積が便利（$A\cdot B = 0$ は 2 つの簡単な場合に分かれる）。|两个正弦之和化为积：2 倍平均角的正弦乘以半差角的余弦。解方程时积最好用（$A\cdot B = 0$ 分成两个简单情形）。`,
      a: [Y(R`\sin a + \sin b = 2\sin\frac{a + b}{2}\cos\frac{a - b}{2}`, { s: 24 }), W('sums → products: good for equations|somme → produit : utile pour les équations|suma → producto: útil en ecuaciones|和 → 積：方程式に便利|和化积：解方程有用')] },
    { s: R`$\sin 3x + \sin x = 2\sin 2x\cos x$. So $\sin 3x + \sin x = 0$ splits into $\sin 2x = 0$ or $\cos x = 0$.|$\sin 3x + \sin x = 2\sin 2x\cos x$. Donc $\sin 3x + \sin x = 0$ se scinde en $\sin 2x = 0$ ou $\cos x = 0$.|$\sin 3x + \sin x = 2\sin 2x\cos x$. Así, $\sin 3x + \sin x = 0$ se separa en $\sin 2x = 0$ o $\cos x = 0$.|$\sin 3x + \sin x = 2\sin 2x\cos x$。$\sin 3x + \sin x = 0$ は $\sin 2x = 0$ または $\cos x = 0$ に分かれる。|$\sin 3x + \sin x = 2\sin 2x\cos x$。于是 $\sin 3x + \sin x = 0$ 分成 $\sin 2x = 0$ 或 $\cos x = 0$。`,
      a: [F(R`\sin 3x + \sin x = 2\sin 2x\cos x`), Y(R`= 0 \iff \sin 2x = 0\ \text{or}\ \cos x = 0`)] },
    { a: [F(R`\sin\tfrac{5\pi}{12} + \sin\tfrac{\pi}{12}`)],
      ex: { k: 'val', v: 'sqrt(6)/2', q: R`Compute $\sin\tfrac{5\pi}{12} + \sin\tfrac{\pi}{12}$ exactly.|Calculez exactement $\sin\tfrac{5\pi}{12} + \sin\tfrac{\pi}{12}$.|Calcula exactamente $\sin\tfrac{5\pi}{12} + \sin\tfrac{\pi}{12}$.|$\sin\tfrac{5\pi}{12} + \sin\tfrac{\pi}{12}$ の厳密な値を求めよ。|精确计算 $\sin\tfrac{5\pi}{12} + \sin\tfrac{\pi}{12}$。`,
        sol: [R`= 2\sin\frac{\pi}{4}\cos\frac{\pi}{6}`, R`= 2\cdot\frac{\sqrt2}2\cdot\frac{\sqrt3}2 = \frac{\sqrt6}{2}`] } });

  lesson('Sums and products/', 'Cosine sums and products|Sommes et produits de cosinus|Sumas y productos de cosenos|cos の和積・積和|余弦的和积互化',
    { s: R`The cosine versions follow the same pattern. Sum of cosines: cosine of the average times cosine of the half-difference. A product of cosines turns into half the sum of the cosines of the difference and the sum — the trick used to integrate products.|Les versions cosinus suivent le même schéma. Somme de cosinus : cosinus de la moyenne fois cosinus de la demi-différence. Un produit de cosinus devient la demi-somme des cosinus de la différence et de la somme — l’astuce pour intégrer des produits.|Las versiones con coseno siguen el mismo patrón. Suma de cosenos: coseno de la media por coseno de la semidiferencia. Un producto de cosenos pasa a la semisuma de los cosenos de la diferencia y de la suma: el truco para integrar productos.|cos の場合も同じ形。cos の和は平均の cos × 半差の cos × 2。cos の積は差と和の cos の和の半分（積の積分に使う）。|余弦版本同样规律。余弦之和：2 倍平均角余弦乘半差角余弦。余弦之积化为差角与和角余弦之和的一半——积分乘积时用的技巧。`,
      a: [F(R`\cos a + \cos b = 2\cos\frac{a + b}{2}\cos\frac{a - b}{2}`, { s: 22 }), F(R`\cos a - \cos b = -2\sin\frac{a + b}{2}\sin\frac{a - b}{2}`, { s: 22 }), Y(R`\cos a\cos b = \tfrac12[\cos(a - b) + \cos(a + b)]`, { s: 22 })] },
    { s: R`$\cos 75^\circ + \cos 15^\circ = 2\cos 45^\circ\cos 30^\circ = 2\cdot\tfrac{\sqrt2}2\cdot\tfrac{\sqrt3}2 = \tfrac{\sqrt6}2$.|$\cos 75^\circ + \cos 15^\circ = 2\cos 45^\circ\cos 30^\circ = \tfrac{\sqrt6}2$.|$\cos 75^\circ + \cos 15^\circ = 2\cos 45^\circ\cos 30^\circ = \tfrac{\sqrt6}2$.|$\cos 75^\circ + \cos 15^\circ = 2\cos 45^\circ\cos 30^\circ = \tfrac{\sqrt6}2$。|$\cos 75^\circ + \cos 15^\circ = 2\cos 45^\circ\cos 30^\circ = \tfrac{\sqrt6}2$。`,
      a: [F(R`\cos 75^\circ + \cos 15^\circ = 2\cos 45^\circ\cos 30^\circ`), Y(R`= \frac{\sqrt6}{2}`)] },
    { a: [F(R`\cos 75^\circ\cos 15^\circ`)],
      ex: { k: 'val', v: '1/4', q: R`Compute $\cos 75^\circ\cos 15^\circ$ exactly.|Calculez exactement $\cos 75^\circ\cos 15^\circ$.|Calcula exactamente $\cos 75^\circ\cos 15^\circ$.|$\cos 75^\circ\cos 15^\circ$ の厳密な値を求めよ。|精确计算 $\cos 75^\circ\cos 15^\circ$。`,
        sol: [R`= \tfrac12[\cos 60^\circ + \cos 90^\circ]`, R`= \tfrac12\left[\tfrac12 + 0\right] = \tfrac14`] } });

  lesson('Sums and products/Product to sum', 'Product to sum|Produit en somme|Producto a suma|積和公式|积化和差',
    { s: R`The reverse direction: a product $\sin a\cos b$ becomes half the sum of $\sin(a + b)$ and $\sin(a - b)$. It is exactly the sum of the two addition formulas. You need it to integrate $\sin 3x\cos x$ and similar products.|Dans l’autre sens : un produit $\sin a\cos b$ devient la demi-somme de $\sin(a + b)$ et $\sin(a - b)$. C’est la somme des deux formules d’addition. Indispensable pour intégrer $\sin 3x\cos x$ et produits semblables.|En sentido inverso: un producto $\sin a\cos b$ se convierte en la semisuma de $\sin(a + b)$ y $\sin(a - b)$. Es justo la suma de las dos fórmulas de la suma. Hace falta para integrar $\sin 3x\cos x$ y productos parecidos.|逆向き：積 $\sin a\cos b$ は $\sin(a + b)$ と $\sin(a - b)$ の和の半分。2 つの加法定理を足したもの。$\sin 3x\cos x$ などの積分に必要。|反方向：积 $\sin a\cos b$ 化为 $\sin(a + b)$ 与 $\sin(a - b)$ 之和的一半，正是两个和角公式相加。积分 $\sin 3x\cos x$ 之类的乘积要用它。`,
      a: [Y(R`\sin a\cos b = \tfrac12[\sin(a + b) + \sin(a - b)]`, { s: 24 }), F(R`\sin 3x\cos x = \tfrac12[\sin 4x + \sin 2x]`)] },
    { s: R`$\sin 75^\circ\cos 15^\circ = \tfrac12[\sin 90^\circ + \sin 60^\circ] = \tfrac12\left(1 + \tfrac{\sqrt3}2\right) = \tfrac{2 + \sqrt3}{4}$.|$\sin 75^\circ\cos 15^\circ = \tfrac12[\sin 90^\circ + \sin 60^\circ] = \tfrac{2 + \sqrt3}{4}$.|$\sin 75^\circ\cos 15^\circ = \tfrac12[\sin 90^\circ + \sin 60^\circ] = \tfrac{2 + \sqrt3}{4}$.|$\sin 75^\circ\cos 15^\circ = \tfrac12[\sin 90^\circ + \sin 60^\circ] = \tfrac{2 + \sqrt3}{4}$。|$\sin 75^\circ\cos 15^\circ = \tfrac12[\sin 90^\circ + \sin 60^\circ] = \tfrac{2 + \sqrt3}{4}$。`,
      a: [F(R`\sin 75^\circ\cos 15^\circ = \tfrac12[\sin 90^\circ + \sin 60^\circ]`), Y(R`= \frac{2 + \sqrt3}{4}`)] },
    { a: [F(R`\sin 52.5^\circ\cos 7.5^\circ`)],
      ex: { k: 'val', v: '(sqrt(3)+sqrt(2))/4', q: R`Compute $\sin 52.5^\circ\cos 7.5^\circ$ exactly.|Calculez exactement $\sin 52{,}5^\circ\cos 7{,}5^\circ$.|Calcula exactamente $\sin 52{,}5^\circ\cos 7{,}5^\circ$.|$\sin 52.5^\circ\cos 7.5^\circ$ の厳密な値を求めよ。|精确计算 $\sin 52.5^\circ\cos 7.5^\circ$。`,
        sol: [R`= \tfrac12[\sin 60^\circ + \sin 45^\circ]`, R`= \tfrac12\left[\tfrac{\sqrt3}2 + \tfrac{\sqrt2}2\right] = \frac{\sqrt3 + \sqrt2}{4}`] } });

  // =============================== Solving triangles ===============================
  const tri3 = (A, B, C, labs) => TRI([A, B, C], labs);
  lesson('Solving triangles/Law of sines', 'Law of sines|Loi des sinus|Teorema del seno|正弦定理|正弦定理',
    { s: R`In any triangle each side is proportional to the sine of the opposite angle, and the common ratio is the diameter $2R$ of the circumscribed circle. Use it when you know an angle and its opposite side, plus one more side or angle.|Dans tout triangle, chaque côté est proportionnel au sinus de l’angle opposé, et le rapport commun est le diamètre $2R$ du cercle circonscrit. On l’utilise quand on connaît un angle et le côté opposé, plus un autre côté ou angle.|En cualquier triángulo cada lado es proporcional al seno del ángulo opuesto, y la razón común es el diámetro $2R$ de la circunferencia circunscrita. Úsalo cuando conoces un ángulo y su lado opuesto, más otro lado o ángulo.|どんな三角形でも各辺は対角の sin に比例し、比は外接円の直径 $2R$。角とその対辺、さらにもう 1 つの辺か角がわかるときに使う。|任何三角形中各边与其对角的正弦成正比，比值为外接圆直径 $2R$。已知一个角及其对边，再加一条边或一个角时使用。`,
      a: [Y(R`\frac{a}{\sin A} = \frac{b}{\sin B} = \frac{c}{\sin C} = 2R`), W('a side and its opposite angle + one more|un côté et son angle opposé + une donnée|un lado y su ángulo opuesto + otro dato|辺とその対角 + もう 1 つ|一边及其对角 + 另一条件'), ...tri3([0, 0], [5, 0], [1.5, 2.6], [[0.5, 0.25, 'A', 'o'], [4.4, 0.2, 'B', 'o'], [1.5, 2.25, 'C', 'o'], [3.4, 1.5, 'a'], [0.5, 1.4, 'b'], [2.5, -0.3, 'c']])] },
    { s: R`$A = 30^\circ$, $B = 45^\circ$, $a = 4$: $b = \dfrac{a\sin B}{\sin A} = \dfrac{4\cdot\tfrac{\sqrt2}2}{\tfrac12} = 4\sqrt2$.|$A = 30^\circ$, $B = 45^\circ$, $a = 4$ : $b = \dfrac{a\sin B}{\sin A} = \dfrac{4\cdot\tfrac{\sqrt2}2}{\tfrac12} = 4\sqrt2$.|$A = 30^\circ$, $B = 45^\circ$, $a = 4$: $b = \dfrac{a\sin B}{\sin A} = \dfrac{4\cdot\tfrac{\sqrt2}2}{\tfrac12} = 4\sqrt2$.|$A = 30^\circ$, $B = 45^\circ$, $a = 4$：$b = \dfrac{a\sin B}{\sin A} = 4\sqrt2$。|$A = 30^\circ$，$B = 45^\circ$，$a = 4$：$b = \dfrac{a\sin B}{\sin A} = 4\sqrt2$。`,
      a: [F(R`b = \frac{a\sin B}{\sin A} = \frac{4\cdot\tfrac{\sqrt2}2}{\tfrac12}`), Y(R`= 4\sqrt2`)] },
    { a: [F(R`A = 45^\circ,\ B = 60^\circ,\ a = 10`)],
      ex: { k: 'val', v: '5sqrt(6)', q: R`In a triangle $A = 45^\circ$, $B = 60^\circ$ and $a = 10$. Find $b$.|Dans un triangle, $A = 45^\circ$, $B = 60^\circ$ et $a = 10$. Calculez $b$.|En un triángulo $A = 45^\circ$, $B = 60^\circ$ y $a = 10$. Halla $b$.|三角形で $A = 45^\circ$, $B = 60^\circ$, $a = 10$。$b$ を求めよ。|三角形中 $A = 45^\circ$，$B = 60^\circ$，$a = 10$，求 $b$。`,
        sol: [R`b = \frac{10\sin 60^\circ}{\sin 45^\circ} = \frac{10\cdot\tfrac{\sqrt3}2}{\tfrac{\sqrt2}2}`, R`= 10\sqrt{\tfrac32} = 5\sqrt6 \approx 12.25`] } });

  lesson('Solving triangles/Law of cosines', 'Law of cosines|Loi des cosinus (Al-Kashi)|Teorema del coseno|余弦定理|余弦定理',
    { s: R`Pythagoras with a correction term: $c^2 = a^2 + b^2 - 2ab\cos C$. When $C = 90^\circ$ the correction vanishes. Use it when you know two sides and the angle between them (SAS), or all three sides.|Pythagore avec un terme correctif : $c^2 = a^2 + b^2 - 2ab\cos C$. Quand $C = 90^\circ$ la correction disparaît. On l’utilise avec deux côtés et l’angle compris, ou les trois côtés.|Pitágoras con un término de corrección: $c^2 = a^2 + b^2 - 2ab\cos C$. Si $C = 90^\circ$ la corrección desaparece. Úsalo cuando conoces dos lados y el ángulo entre ellos, o los tres lados.|補正項つきの三平方の定理：$c^2 = a^2 + b^2 - 2ab\cos C$。$C = 90^\circ$ で補正は消える。2 辺とその間の角、または 3 辺がわかるときに使う。|带修正项的勾股定理：$c^2 = a^2 + b^2 - 2ab\cos C$。$C = 90^\circ$ 时修正项消失。已知两边及夹角，或三边时使用。`,
      a: [Y(R`c^2 = a^2 + b^2 - 2ab\cos C`), W('two sides and the angle between them|deux côtés et l’angle compris|dos lados y el ángulo entre ellos|2 辺とその間の角|两边及其夹角'), ...tri3([0, 0], [5, 0], [1.5, 2.6], [[1.5, 2.25, 'C', 'o'], [3.4, 1.5, 'a'], [0.5, 1.4, 'b'], [2.5, -0.3, 'c']])] },
    { s: R`$a = 5$, $b = 8$, $C = 60^\circ$: $c^2 = 25 + 64 - 2\cdot 5\cdot 8\cdot\tfrac12 = 49$, so $c = 7$.|$a = 5$, $b = 8$, $C = 60^\circ$ : $c^2 = 25 + 64 - 2\cdot 5\cdot 8\cdot\tfrac12 = 49$, donc $c = 7$.|$a = 5$, $b = 8$, $C = 60^\circ$: $c^2 = 25 + 64 - 2\cdot 5\cdot 8\cdot\tfrac12 = 49$, así que $c = 7$.|$a = 5$, $b = 8$, $C = 60^\circ$：$c^2 = 25 + 64 - 40 = 49$、$c = 7$。|$a = 5$，$b = 8$，$C = 60^\circ$：$c^2 = 25 + 64 - 40 = 49$，$c = 7$。`,
      a: [F(R`c^2 = 25 + 64 - 2\cdot 5\cdot 8\cdot\tfrac12 = 49`), Y(R`c = 7`)] },
    { a: [F(R`a = 4,\ b = 6,\ C = 60^\circ`)],
      ex: { k: 'val', v: '2sqrt(7)', q: R`In a triangle $a = 4$, $b = 6$ and $C = 60^\circ$. Find $c$.|Dans un triangle, $a = 4$, $b = 6$ et $C = 60^\circ$. Calculez $c$.|En un triángulo $a = 4$, $b = 6$ y $C = 60^\circ$. Halla $c$.|三角形で $a = 4$, $b = 6$, $C = 60^\circ$。$c$ を求めよ。|三角形中 $a = 4$，$b = 6$，$C = 60^\circ$，求 $c$。`,
        sol: [R`c^2 = 16 + 36 - 2\cdot 4\cdot 6\cdot\tfrac12 = 28`, R`c = \sqrt{28} = 2\sqrt7 \approx 5.29`] } });

  lesson('Solving triangles/Angle from the sides', 'An angle from the three sides|Un angle à partir des trois côtés|Un ángulo a partir de los lados|3 辺から角を求める|由三边求角',
    { s: R`Solve the law of cosines for $\cos C$. The sign tells the shape: positive means $C$ is acute, 0 means right, negative means obtuse. The largest angle is opposite the largest side — check that one to classify the triangle.|On isole $\cos C$ dans la loi des cosinus. Le signe renseigne : positif, $C$ aigu ; nul, droit ; négatif, obtus. Le plus grand angle est opposé au plus grand côté — c’est lui qu’on teste pour classer le triangle.|Despeja $\cos C$ del teorema del coseno. El signo indica la forma: positivo, $C$ agudo; 0, recto; negativo, obtuso. El mayor ángulo está frente al mayor lado: compruébalo para clasificar el triángulo.|余弦定理を $\cos C$ について解く。正なら鋭角、0 なら直角、負なら鈍角。最大の角は最大の辺の対角なので、それを調べれば三角形の形がわかる。|由余弦定理解出 $\cos C$。符号说明形状：正为锐角，0 为直角，负为钝角。最大角对最大边——检验它即可判断三角形类型。`,
      a: [Y(R`\cos C = \frac{a^2 + b^2 - c^2}{2ab}`), W('> 0 acute,  = 0 right,  < 0 obtuse|> 0 aigu,  = 0 droit,  < 0 obtus|> 0 agudo,  = 0 recto,  < 0 obtuso|> 0 鋭角、= 0 直角、< 0 鈍角|> 0 锐角，= 0 直角，< 0 钝角')] },
    { s: R`Sides 3, 4, 5: the angle opposite 5 has $\cos C = \tfrac{9 + 16 - 25}{24} = 0$, so it is a right angle — Pythagoras again.|Côtés 3, 4, 5 : l’angle opposé à 5 a $\cos C = \tfrac{9 + 16 - 25}{24} = 0$, c’est un angle droit — Pythagore encore.|Lados 3, 4, 5: el ángulo opuesto a 5 tiene $\cos C = \tfrac{9 + 16 - 25}{24} = 0$, es recto: otra vez Pitágoras.|3 辺 3, 4, 5：5 の対角は $\cos C = \tfrac{9 + 16 - 25}{24} = 0$ で直角。|三边 3、4、5：5 的对角 $\cos C = \tfrac{9 + 16 - 25}{24} = 0$，是直角。`,
      a: [F(R`\cos C = \frac{9 + 16 - 25}{2\cdot 3\cdot 4} = 0`), Y(R`C = 90^\circ`)] },
    { a: [F(R`a = 3,\ b = 5,\ c = 7`)],
      ex: { k: 'val', v: '120', q: R`A triangle has sides $3$, $5$ and $7$. Find its largest angle, in degrees.|Un triangle a pour côtés $3$, $5$ et $7$. Trouvez son plus grand angle, en degrés.|Un triángulo tiene lados $3$, $5$ y $7$. Halla su mayor ángulo, en grados.|3 辺が $3$, $5$, $7$ の三角形の最大の角を度で求めよ。|三角形三边为 $3$, $5$, $7$，求最大角（度）。`,
        sol: [R`\text{opposite } 7:\ \cos C = \frac{9 + 25 - 49}{2\cdot 3\cdot 5}`, R`= -\frac{15}{30} = -\frac12`, R`C = 120^\circ`] } });

  lesson('Solving triangles/Area', 'Area with a sine|Aire avec un sinus|Área con un seno|sin を使った面積|用正弦求面积',
    { s: R`Base $a$, and the height from the third vertex is $b\sin C$. So the area is half of two sides times the sine of the angle between them — no need to compute the height separately.|Base $a$, et la hauteur issue du troisième sommet vaut $b\sin C$. L’aire est donc la moitié du produit de deux côtés par le sinus de l’angle compris — inutile de calculer la hauteur à part.|Base $a$, y la altura desde el tercer vértice es $b\sin C$. Así el área es la mitad de dos lados por el seno del ángulo entre ellos, sin calcular la altura aparte.|底辺 $a$、3 つ目の頂点からの高さは $b\sin C$。面積は 2 辺とその間の角の sin の積の半分（高さを別に求めなくてよい）。|底为 $a$，第三个顶点到它的高为 $b\sin C$。所以面积是两边与夹角正弦之积的一半——不必另求高。`,
      a: [Y(R`S = \tfrac12 ab\sin C`), F(R`= \frac{abc}{4R}`), ...tri3([0, 0], [5, 0], [1.5, 2.6], [[0.4, 0.3, 'C', 'o'], [2.5, -0.3, 'a'], [0.4, 1.5, 'b']]), ['seg', P2(1.5, 2.6), P2(1.5, 0), { c: 'g', dash: true }], ['lab3', P2(1.5, 1.2), 'b sin C', { c: 'g', dx: 6 }]] },
    { s: R`Two sides 6 and 8 with $30^\circ$ between them: $S = \tfrac12\cdot 6\cdot 8\cdot\tfrac12 = 12$.|Deux côtés 6 et 8 formant $30^\circ$ : $S = \tfrac12\cdot 6\cdot 8\cdot\tfrac12 = 12$.|Dos lados 6 y 8 con $30^\circ$ entre ellos: $S = \tfrac12\cdot 6\cdot 8\cdot\tfrac12 = 12$.|2 辺 6, 8、その間の角 $30^\circ$：$S = 12$。|两边 6、8，夹角 $30^\circ$：$S = 12$。`,
      a: [Y(R`S = \tfrac12\cdot 6\cdot 8\cdot\sin 30^\circ = 12`)] },
    { a: [F(R`a = 5,\ b = 7,\ C = 150^\circ`)],
      ex: { k: 'val', v: '35/4', q: R`Find the area of a triangle with $a = 5$, $b = 7$ and $C = 150^\circ$.|Calculez l’aire d’un triangle avec $a = 5$, $b = 7$ et $C = 150^\circ$.|Calcula el área de un triángulo con $a = 5$, $b = 7$ y $C = 150^\circ$.|$a = 5$, $b = 7$, $C = 150^\circ$ の三角形の面積を求めよ。|求 $a = 5$，$b = 7$，$C = 150^\circ$ 的三角形面积。`,
        sol: [R`\sin 150^\circ = \tfrac12`, R`S = \tfrac12\cdot 5\cdot 7\cdot\tfrac12 = \tfrac{35}{4}`] } });

  lesson('Solving triangles/Ambiguous case (SSA)', 'The ambiguous case (SSA)|Le cas ambigu (CCA)|El caso ambiguo (LLA)|2 辺と 1 角（あいまいな場合）|边边角的歧义情形',
    { s: R`Knowing two sides and an angle that is not between them, the law of sines gives $\sin B$. Then: if $\sin B > 1$ there is no triangle; if $\sin B = 1$ exactly one (right angle); if $\sin B < 1$ both $B$ and $180^\circ - B$ may work — keep each one only if the angles still add up to less than $180^\circ$.|Avec deux côtés et un angle non compris, la loi des sinus donne $\sin B$. Alors : si $\sin B > 1$, aucun triangle ; si $\sin B = 1$, un seul (angle droit) ; si $\sin B < 1$, $B$ et $180^\circ - B$ peuvent convenir — on garde chacun seulement si la somme des angles reste inférieure à $180^\circ$.|Con dos lados y un ángulo que no está entre ellos, el teorema del seno da $\sin B$. Si $\sin B > 1$ no hay triángulo; si $\sin B = 1$ hay uno (recto); si $\sin B < 1$ pueden valer $B$ y $180^\circ - B$: conserva cada uno solo si los ángulos siguen sumando menos de $180^\circ$.|2 辺と、その間でない角がわかると正弦定理で $\sin B$ が出る。$\sin B > 1$ なら三角形なし、$= 1$ なら 1 つ（直角）、$< 1$ なら $B$ と $180^\circ - B$ の両方の可能性（角の和が $180^\circ$ 未満なら採用）。|已知两边和一个非夹角，由正弦定理得 $\sin B$。若 $\sin B > 1$：无三角形；$\sin B = 1$：恰一个（直角）；$\sin B < 1$：$B$ 和 $180^\circ - B$ 都可能——只要角和仍小于 $180^\circ$ 就保留。`,
      a: [Y(R`\sin B = \frac{b\sin A}{a}`), F(R`> 1:\ 0,\quad = 1:\ 1,\quad < 1:\ B\ \text{or}\ 180^\circ - B`)] },
    { s: R`$A = 30^\circ$, $a = 6$, $b = 8$: $\sin B = \tfrac{8\cdot\tfrac12}{6} = \tfrac23$, so $B \approx 41.8^\circ$ or $B \approx 138.2^\circ$. Both leave room for $C$ ($30 + 138.2 < 180$): two triangles.|$A = 30^\circ$, $a = 6$, $b = 8$ : $\sin B = \tfrac{8\cdot\tfrac12}{6} = \tfrac23$, donc $B \approx 41{,}8^\circ$ ou $B \approx 138{,}2^\circ$. Les deux laissent de la place pour $C$ : deux triangles.|$A = 30^\circ$, $a = 6$, $b = 8$: $\sin B = \tfrac{8\cdot\tfrac12}{6} = \tfrac23$, luego $B \approx 41{,}8^\circ$ o $B \approx 138{,}2^\circ$. Los dos dejan sitio a $C$: dos triángulos.|$A = 30^\circ$, $a = 6$, $b = 8$：$\sin B = \tfrac23$ で $B \approx 41.8^\circ$ または $138.2^\circ$。どちらも $C$ の余地があり、三角形は 2 つ。|$A = 30^\circ$，$a = 6$，$b = 8$：$\sin B = \tfrac23$，$B \approx 41.8^\circ$ 或 $138.2^\circ$。两者都给 $C$ 留有余地：两个三角形。`,
      a: [F(R`\sin B = \frac{8\cdot\tfrac12}{6} = \frac23`), Y(R`B \approx 41.8^\circ\ \text{or}\ 138.2^\circ:\ 2\ \text{triangles}`), AX([-0.2, 3.4], [-0.3, 1.2]), P('y=sin(x)'), P('y=2/3', 'b'), PT(Math.asin(2 / 3), 2 / 3, ''), PT(PI - Math.asin(2 / 3), 2 / 3, '')] },
    { a: [F(R`A = 30^\circ,\ a = 5,\ b = 10`)],
      ex: { k: 'val', v: '1', q: R`How many triangles have $A = 30^\circ$, $a = 5$ and $b = 10$?|Combien de triangles vérifient $A = 30^\circ$, $a = 5$ et $b = 10$ ?|¿Cuántos triángulos tienen $A = 30^\circ$, $a = 5$ y $b = 10$?|$A = 30^\circ$, $a = 5$, $b = 10$ となる三角形はいくつあるか。|满足 $A = 30^\circ$，$a = 5$，$b = 10$ 的三角形有几个？`,
        sol: [R`\sin B = \frac{10\cdot\tfrac12}{5} = 1`, R`B = 90^\circ\ \text{only}`, R`1\ \text{triangle}`] } });

  // =============================== Sinusoids ===============================
  lesson('Sinusoids/General sinusoid', 'The general sinusoid|La sinusoïde générale|La sinusoide general|一般の正弦曲線|一般正弦曲线',
    { s: R`Each letter does one job. $A$ stretches vertically (amplitude $\lvert A\rvert$), $\omega$ squeezes horizontally (period $\tfrac{2\pi}\omega$), $\varphi$ shifts sideways (by $-\tfrac\varphi\omega$), and $D$ lifts the midline. Max is $D + \lvert A\rvert$, min is $D - \lvert A\rvert$.|Chaque lettre a un rôle. $A$ étire verticalement (amplitude $\lvert A\rvert$), $\omega$ comprime horizontalement (période $\tfrac{2\pi}\omega$), $\varphi$ décale latéralement (de $-\tfrac\varphi\omega$), et $D$ monte la ligne médiane. Max $D + \lvert A\rvert$, min $D - \lvert A\rvert$.|Cada letra hace una cosa. $A$ estira en vertical (amplitud $\lvert A\rvert$), $\omega$ comprime en horizontal (periodo $\tfrac{2\pi}\omega$), $\varphi$ desplaza de lado (en $-\tfrac\varphi\omega$) y $D$ sube la línea media. Máximo $D + \lvert A\rvert$, mínimo $D - \lvert A\rvert$.|各文字に役割がある。$A$ は縦に伸ばす（振幅 $\lvert A\rvert$）、$\omega$ は横に縮める（周期 $\tfrac{2\pi}\omega$）、$\varphi$ は横にずらす（$-\tfrac\varphi\omega$）、$D$ は中心線を上げる。最大 $D + \lvert A\rvert$、最小 $D - \lvert A\rvert$。|每个字母各司其职。$A$ 竖直拉伸（振幅 $\lvert A\rvert$），$\omega$ 水平压缩（周期 $\tfrac{2\pi}\omega$），$\varphi$ 左右平移（$-\tfrac\varphi\omega$），$D$ 抬高中线。最大值 $D + \lvert A\rvert$，最小值 $D - \lvert A\rvert$。`,
      a: [Y(R`y = A\sin(\omega x + \varphi) + D`), F(R`\lvert A\rvert,\quad T = \frac{2\pi}{\omega},\quad \text{shift } -\frac{\varphi}{\omega},\quad \text{midline } y = D`, { s: 22 }), AX([-0.5, 7], [-2.5, 4.5]), P('y=sin(x)', 'b'), P('y=3sin(2x-pi/2)+1', 'y', { d: 400 }), LN(-0.5, 1, 7, 1, 'g', { dash: true })] },
    { s: R`$y = 3\sin(2x - \tfrac\pi2) + 1$: amplitude 3, period $\tfrac{2\pi}2 = \pi$, shifted right by $\tfrac\pi4$, midline $y = 1$, so it goes from $-2$ to $4$.|$y = 3\sin(2x - \tfrac\pi2) + 1$ : amplitude 3, période $\pi$, décalée de $\tfrac\pi4$ vers la droite, ligne médiane $y = 1$ : elle va de $-2$ à $4$.|$y = 3\sin(2x - \tfrac\pi2) + 1$: amplitud 3, periodo $\pi$, desplazada $\tfrac\pi4$ a la derecha, línea media $y = 1$: va de $-2$ a $4$.|$y = 3\sin(2x - \tfrac\pi2) + 1$：振幅 3、周期 $\pi$、右へ $\tfrac\pi4$、中心線 $y = 1$ で $-2$ から $4$。|$y = 3\sin(2x - \tfrac\pi2) + 1$：振幅 3，周期 $\pi$，右移 $\tfrac\pi4$，中线 $y = 1$，从 $-2$ 到 $4$。`,
      a: [F(R`A = 3,\ \omega = 2,\ \varphi = -\tfrac\pi2,\ D = 1`), Y(R`T = \pi,\ \text{range } [-2, 4]`), AX([-0.5, 7], [-2.5, 4.5]), P('y=3sin(2x-pi/2)+1'), PT(3 * PI / 4, 4, 'max'), PT(PI / 4, 1, R`\tfrac\pi4`)] },
    { a: [F(R`y = 2\sin\left(\tfrac{\pi x}{3}\right) - 1`), AX([-0.5, 13], [-3.5, 1.5]), P('y=2sin(pi*x/3)-1')],
      ex: { k: 'val', v: '6', q: R`What is the period of $y = 2\sin\left(\tfrac{\pi x}{3}\right) - 1$?|Quelle est la période de $y = 2\sin\left(\tfrac{\pi x}{3}\right) - 1$ ?|¿Cuál es el periodo de $y = 2\sin\left(\tfrac{\pi x}{3}\right) - 1$?|$y = 2\sin\left(\tfrac{\pi x}{3}\right) - 1$ の周期を求めよ。|$y = 2\sin\left(\tfrac{\pi x}{3}\right) - 1$ 的周期是多少？`,
        sol: [R`\omega = \frac\pi3`, R`T = \frac{2\pi}{\pi/3} = 6`] } });

  lesson('Sinusoids/Combining sine and cosine', 'a sin x + b cos x|a sin x + b cos x|a sen x + b cos x|a sin x + b cos x の合成|辅助角公式',
    { s: R`A sine plus a cosine of the same angle is always a single shifted sine wave. Its amplitude is $R = \sqrt{a^2 + b^2}$, so the maximum is $R$ and the minimum $-R$ — the standard way to find the extreme values of $a\sin x + b\cos x$.|Un sinus plus un cosinus du même angle est toujours une seule sinusoïde décalée. Son amplitude est $R = \sqrt{a^2 + b^2}$ : le maximum vaut $R$, le minimum $-R$ — la méthode classique pour les extremums de $a\sin x + b\cos x$.|Un seno más un coseno del mismo ángulo siempre es una sola sinusoide desplazada. Su amplitud es $R = \sqrt{a^2 + b^2}$, así que el máximo es $R$ y el mínimo $-R$: el método habitual para los extremos de $a\sin x + b\cos x$.|同じ角の sin と cos の和は常に 1 つのずれた正弦波。振幅は $R = \sqrt{a^2 + b^2}$ で、最大 $R$、最小 $-R$。$a\sin x + b\cos x$ の最大最小の定番の方法。|同角的正弦加余弦总是一条平移的正弦曲线，振幅 $R = \sqrt{a^2 + b^2}$，最大值 $R$，最小值 $-R$——求 $a\sin x + b\cos x$ 最值的标准方法。`,
      a: [Y(R`a\sin x + b\cos x = R\sin(x + \varphi),\ R = \sqrt{a^2 + b^2}`, { s: 22 }), F(R`\cos\varphi = \frac aR,\quad \sin\varphi = \frac bR`), AX([-0.3, 7], [-2.4, 2.4]), P('y=sin(x)', 'b'), P('y=sqrt(3)cos(x)', 'g', { d: 200 }), P('y=sin(x)+sqrt(3)cos(x)', 'y', { d: 500 })] },
    { s: R`$\sin x + \sqrt3\cos x$: $R = \sqrt{1 + 3} = 2$, $\cos\varphi = \tfrac12$ and $\sin\varphi = \tfrac{\sqrt3}2$, so $\varphi = \tfrac\pi3$ and the expression equals $2\sin(x + \tfrac\pi3)$, between $-2$ and $2$.|$\sin x + \sqrt3\cos x$ : $R = \sqrt{1 + 3} = 2$, $\cos\varphi = \tfrac12$ et $\sin\varphi = \tfrac{\sqrt3}2$, donc $\varphi = \tfrac\pi3$ et l’expression vaut $2\sin(x + \tfrac\pi3)$, entre $-2$ et $2$.|$\sin x + \sqrt3\cos x$: $R = \sqrt{1 + 3} = 2$, $\cos\varphi = \tfrac12$ y $\sin\varphi = \tfrac{\sqrt3}2$, así que $\varphi = \tfrac\pi3$ y la expresión es $2\sin(x + \tfrac\pi3)$, entre $-2$ y $2$.|$\sin x + \sqrt3\cos x$：$R = 2$、$\varphi = \tfrac\pi3$ で $2\sin(x + \tfrac\pi3)$、値は $-2$ から $2$。|$\sin x + \sqrt3\cos x$：$R = 2$，$\varphi = \tfrac\pi3$，等于 $2\sin(x + \tfrac\pi3)$，在 $-2$ 与 $2$ 之间。`,
      a: [F(R`R = \sqrt{1 + 3} = 2,\quad \varphi = \tfrac\pi3`), Y(R`\sin x + \sqrt3\cos x = 2\sin\left(x + \tfrac\pi3\right)`), AX([-0.3, 7], [-2.4, 2.4]), P('y=sin(x)+sqrt(3)cos(x)'), PT(PI / 6, 2, 'max = 2')] },
    { a: [F(R`f(x) = 3\sin x + 4\cos x`), AX([-0.3, 7], [-5.5, 5.5]), P('y=3sin(x)+4cos(x)')],
      ex: { k: 'val', v: '5', q: R`Find the maximum value of $3\sin x + 4\cos x$.|Trouvez la valeur maximale de $3\sin x + 4\cos x$.|Halla el valor máximo de $3\sin x + 4\cos x$.|$3\sin x + 4\cos x$ の最大値を求めよ。|求 $3\sin x + 4\cos x$ 的最大值。`,
        sol: [R`R = \sqrt{9 + 16} = 5`, R`3\sin x + 4\cos x = 5\sin(x + \varphi)`, R`\max = 5`] } });

  // =============================== Equations ===============================
  lesson('Equations and inverse functions/sin x = a', 'Solving sin x = a|Résoudre sin x = a|Resolver sen x = a|sin x = a を解く|解 sin x = a',
    { s: R`The horizontal line $y = a$ cuts each wave of the sine twice: at $\arcsin a$ and at its mirror $\pi - \arcsin a$. Then every full turn $2k\pi$ repeats them. Always look for both families.|La droite horizontale $y = a$ coupe chaque arche du sinus deux fois : en $\arcsin a$ et en son symétrique $\pi - \arcsin a$. Puis chaque tour $2k\pi$ les répète. Toujours chercher les deux familles.|La recta horizontal $y = a$ corta cada onda del seno dos veces: en $\arcsin a$ y en su simétrico $\pi - \arcsin a$. Luego cada vuelta $2k\pi$ las repite. Busca siempre las dos familias.|水平線 $y = a$ は sin の 1 周期で 2 回交わる：$\arcsin a$ とその鏡像 $\pi - \arcsin a$。さらに $2k\pi$ ごとに繰り返す。必ず 2 系列を探す。|水平线 $y = a$ 与正弦每个周期交两次：$\arcsin a$ 和对称的 $\pi - \arcsin a$，然后每 $2k\pi$ 重复。一定要找两族解。`,
      a: [Y(R`x = \arcsin a + 2k\pi,\quad x = \pi - \arcsin a + 2k\pi`, { s: 22 }), AX([-0.3, 6.6], [-1.3, 1.3]), P('y=sin(x)'), P('y=0.5', 'b'), PT(PI / 6, 0.5, R`\tfrac\pi6`), PT(5 * PI / 6, 0.5, R`\tfrac{5\pi}6`)] },
    { s: R`$\sin x = \tfrac12$ on $[0, 2\pi)$: $\arcsin\tfrac12 = \tfrac\pi6$ and $\pi - \tfrac\pi6 = \tfrac{5\pi}6$. These are the two crossings shown on the graph.|$\sin x = \tfrac12$ sur $[0, 2\pi[$ : $\arcsin\tfrac12 = \tfrac\pi6$ et $\pi - \tfrac\pi6 = \tfrac{5\pi}6$. Ce sont les deux intersections du graphique.|$\sin x = \tfrac12$ en $[0, 2\pi)$: $\arcsin\tfrac12 = \tfrac\pi6$ y $\pi - \tfrac\pi6 = \tfrac{5\pi}6$. Son los dos cortes de la gráfica.|$[0, 2\pi)$ で $\sin x = \tfrac12$：$\tfrac\pi6$ と $\tfrac{5\pi}6$（グラフの 2 つの交点）。|$[0, 2\pi)$ 内 $\sin x = \tfrac12$：$\tfrac\pi6$ 和 $\tfrac{5\pi}6$（图上的两个交点）。`,
      a: [F(R`\arcsin\tfrac12 = \tfrac\pi6`), Y(R`x = \tfrac\pi6,\ \tfrac{5\pi}6`), AX([-0.3, 6.6], [-1.3, 1.3]), P('y=sin(x)'), P('y=0.5', 'b'), PT(PI / 6, 0.5, R`\tfrac\pi6`), PT(5 * PI / 6, 0.5, R`\tfrac{5\pi}6`)] },
    { a: [F(R`\sin x = -\tfrac{\sqrt2}{2},\quad 0 \le x < 2\pi`), AX([-0.3, 6.6], [-1.3, 1.3]), P('y=sin(x)'), P('y=-sqrt(2)/2', 'b')],
      ex: { k: 'roots', v: ['5pi/4', '7pi/4'], q: R`Solve $\sin x = -\tfrac{\sqrt2}{2}$ for $0 \le x < 2\pi$.|Résolvez $\sin x = -\tfrac{\sqrt2}{2}$ pour $0 \le x < 2\pi$.|Resuelve $\sin x = -\tfrac{\sqrt2}{2}$ para $0 \le x < 2\pi$.|$0 \le x < 2\pi$ で $\sin x = -\tfrac{\sqrt2}{2}$ を解け。|在 $0 \le x < 2\pi$ 内解 $\sin x = -\tfrac{\sqrt2}{2}$。`,
        sol: [R`\arcsin\left(-\tfrac{\sqrt2}2\right) = -\tfrac\pi4 \equiv \tfrac{7\pi}4`, R`\pi - \left(-\tfrac\pi4\right) = \tfrac{5\pi}4`, R`x = \tfrac{5\pi}4,\ \tfrac{7\pi}4`] } });

  lesson('Equations and inverse functions/cos x = a', 'Solving cos x = a|Résoudre cos x = a|Resolver cos x = a|cos x = a を解く|解 cos x = a',
    { s: R`Cosine is even, so the two solutions are mirror images across the $y$-axis: $\pm\arccos a$, plus full turns. In $[0, 2\pi)$ write $-\arccos a$ as $2\pi - \arccos a$.|Le cosinus est pair : les deux solutions sont symétriques par rapport à l’axe des $y$ : $\pm\arccos a$, plus des tours complets. Dans $[0, 2\pi[$ on écrit $-\arccos a$ sous la forme $2\pi - \arccos a$.|El coseno es par, así que las dos soluciones son simétricas respecto al eje $y$: $\pm\arccos a$, más vueltas completas. En $[0, 2\pi)$ escribe $-\arccos a$ como $2\pi - \arccos a$.|cos は偶関数なので 2 解は $y$ 軸対称：$\pm\arccos a$ に周期を加える。$[0, 2\pi)$ では $-\arccos a$ を $2\pi - \arccos a$ と書く。|余弦是偶函数，两解关于 $y$ 轴对称：$\pm\arccos a$ 加整圈。在 $[0, 2\pi)$ 内把 $-\arccos a$ 写成 $2\pi - \arccos a$。`,
      a: [Y(R`x = \pm\arccos a + 2k\pi`), AX([-0.3, 6.6], [-1.3, 1.3]), P('y=cos(x)'), P('y=0.5', 'b'), PT(PI / 3, 0.5, R`\tfrac\pi3`), PT(5 * PI / 3, 0.5, R`\tfrac{5\pi}3`)] },
    { s: R`$\cos x = \tfrac12$: $\arccos\tfrac12 = \tfrac\pi3$, so $x = \tfrac\pi3$ or $x = 2\pi - \tfrac\pi3 = \tfrac{5\pi}3$ in $[0, 2\pi)$.|$\cos x = \tfrac12$ : $\arccos\tfrac12 = \tfrac\pi3$, donc $x = \tfrac\pi3$ ou $x = 2\pi - \tfrac\pi3 = \tfrac{5\pi}3$ dans $[0, 2\pi[$.|$\cos x = \tfrac12$: $\arccos\tfrac12 = \tfrac\pi3$, así que $x = \tfrac\pi3$ o $x = 2\pi - \tfrac\pi3 = \tfrac{5\pi}3$ en $[0, 2\pi)$.|$\cos x = \tfrac12$：$x = \tfrac\pi3$, $\tfrac{5\pi}3$。|$\cos x = \tfrac12$：$x = \tfrac\pi3$ 或 $\tfrac{5\pi}3$。`,
      a: [F(R`\arccos\tfrac12 = \tfrac\pi3`), Y(R`x = \tfrac\pi3,\ \tfrac{5\pi}3`)] },
    { a: [F(R`2\cos x + 1 = 0,\quad 0 \le x < 2\pi`), AX([-0.3, 6.6], [-1.3, 1.3]), P('y=cos(x)'), P('y=-0.5', 'b')],
      ex: { k: 'roots', v: ['2pi/3', '4pi/3'], q: R`Solve $2\cos x + 1 = 0$ for $0 \le x < 2\pi$.|Résolvez $2\cos x + 1 = 0$ pour $0 \le x < 2\pi$.|Resuelve $2\cos x + 1 = 0$ para $0 \le x < 2\pi$.|$0 \le x < 2\pi$ で $2\cos x + 1 = 0$ を解け。|在 $0 \le x < 2\pi$ 内解 $2\cos x + 1 = 0$。`,
        sol: [R`\cos x = -\tfrac12`, R`\arccos\left(-\tfrac12\right) = \tfrac{2\pi}3`, R`x = \tfrac{2\pi}3,\ 2\pi - \tfrac{2\pi}3 = \tfrac{4\pi}3`] } });

  lesson('Equations and inverse functions/tan x = a', 'Solving tan x = a|Résoudre tan x = a|Resolver tan x = a|tan x = a を解く|解 tan x = a',
    { s: R`Tangent takes every value exactly once per period $\pi$, so there is a single family: $\arctan a + k\pi$. In $[0, 2\pi)$ that gives two solutions, half a turn apart.|La tangente prend chaque valeur une seule fois par période $\pi$ : une seule famille, $\arctan a + k\pi$. Dans $[0, 2\pi[$ cela donne deux solutions, à un demi-tour d’écart.|La tangente toma cada valor exactamente una vez por periodo $\pi$, así que hay una sola familia: $\arctan a + k\pi$. En $[0, 2\pi)$ salen dos soluciones separadas media vuelta.|tan は周期 $\pi$ ごとにすべての値をちょうど 1 回とるので、解は 1 系列 $\arctan a + k\pi$。$[0, 2\pi)$ では半回転離れた 2 解。|正切每个周期 $\pi$ 取每个值恰一次，只有一族解：$\arctan a + k\pi$。在 $[0, 2\pi)$ 内有相差半圈的两个解。`,
      a: [Y(R`x = \arctan a + k\pi`), AX([-0.3, 6.6], [-3, 3]), P('y=tan(x)'), P('y=1', 'b'), PT(PI / 4, 1, R`\tfrac\pi4`), PT(5 * PI / 4, 1, R`\tfrac{5\pi}4`)] },
    { s: R`$\tan x = 1$: $\arctan 1 = \tfrac\pi4$, so $x = \tfrac\pi4$ and $x = \tfrac\pi4 + \pi = \tfrac{5\pi}4$ in $[0, 2\pi)$.|$\tan x = 1$ : $\arctan 1 = \tfrac\pi4$, donc $x = \tfrac\pi4$ et $x = \tfrac{5\pi}4$ dans $[0, 2\pi[$.|$\tan x = 1$: $\arctan 1 = \tfrac\pi4$, así que $x = \tfrac\pi4$ y $x = \tfrac{5\pi}4$ en $[0, 2\pi)$.|$\tan x = 1$：$x = \tfrac\pi4$, $\tfrac{5\pi}4$。|$\tan x = 1$：$x = \tfrac\pi4$ 和 $\tfrac{5\pi}4$。`,
      a: [F(R`\arctan 1 = \tfrac\pi4`), Y(R`x = \tfrac\pi4,\ \tfrac{5\pi}4`)] },
    { a: [F(R`\tan x = -\sqrt3,\quad 0 \le x < 2\pi`), AX([-0.3, 6.6], [-3, 3]), P('y=tan(x)'), P('y=-sqrt(3)', 'b')],
      ex: { k: 'roots', v: ['2pi/3', '5pi/3'], q: R`Solve $\tan x = -\sqrt3$ for $0 \le x < 2\pi$.|Résolvez $\tan x = -\sqrt3$ pour $0 \le x < 2\pi$.|Resuelve $\tan x = -\sqrt3$ para $0 \le x < 2\pi$.|$0 \le x < 2\pi$ で $\tan x = -\sqrt3$ を解け。|在 $0 \le x < 2\pi$ 内解 $\tan x = -\sqrt3$。`,
        sol: [R`\arctan(-\sqrt3) = -\tfrac\pi3`, R`-\tfrac\pi3 + \pi = \tfrac{2\pi}3,\quad -\tfrac\pi3 + 2\pi = \tfrac{5\pi}3`] } });

  lesson('Equations and inverse functions/Ranges', 'Ranges of the inverse functions|Intervalles des fonctions réciproques|Recorridos de las inversas|逆三角関数の値域|反三角函数的值域',
    { s: R`$\arcsin$, $\arccos$ and $\arctan$ return one chosen angle, always in a fixed interval. So $\arcsin(\sin x) = x$ only when $x$ is already in $[-\tfrac\pi2, \tfrac\pi2]$; otherwise find the angle in that interval with the same sine.|$\arcsin$, $\arccos$ et $\arctan$ renvoient un angle choisi, toujours dans un intervalle fixe. Donc $\arcsin(\sin x) = x$ seulement si $x$ est déjà dans $[-\tfrac\pi2, \tfrac\pi2]$ ; sinon on cherche l’angle de cet intervalle qui a le même sinus.|$\arcsin$, $\arccos$ y $\arctan$ devuelven un ángulo concreto, siempre en un intervalo fijo. Así $\arcsin(\sin x) = x$ solo si $x$ ya está en $[-\tfrac\pi2, \tfrac\pi2]$; si no, busca el ángulo de ese intervalo con el mismo seno.|arcsin, arccos, arctan は決まった区間の角を 1 つだけ返す。$\arcsin(\sin x) = x$ は $x$ が $[-\tfrac\pi2, \tfrac\pi2]$ にあるときだけで、そうでなければその区間で同じ sin をもつ角を探す。|$\arcsin$、$\arccos$、$\arctan$ 只返回固定区间内的一个角。所以 $\arcsin(\sin x) = x$ 仅当 $x$ 已在 $[-\tfrac\pi2, \tfrac\pi2]$ 内；否则找该区间内正弦相同的角。`,
      a: [F(R`\arcsin \in [-\tfrac\pi2, \tfrac\pi2],\ \arccos \in [0, \pi],\ \arctan \in (-\tfrac\pi2, \tfrac\pi2)`, { s: 20 }), AX([-1.6, 1.6], [-1.8, 3.4]), P('y=asin(x)'), P('y=acos(x)', 'b', { d: 300 })] },
    { s: R`$\arcsin(\sin\tfrac{3\pi}4)$: $\sin\tfrac{3\pi}4 = \tfrac{\sqrt2}2$, and the angle in $[-\tfrac\pi2, \tfrac\pi2]$ with that sine is $\tfrac\pi4$ — not $\tfrac{3\pi}4$.|$\arcsin(\sin\tfrac{3\pi}4)$ : $\sin\tfrac{3\pi}4 = \tfrac{\sqrt2}2$, et l’angle de $[-\tfrac\pi2, \tfrac\pi2]$ ayant ce sinus est $\tfrac\pi4$ — pas $\tfrac{3\pi}4$.|$\arcsin(\sin\tfrac{3\pi}4)$: $\sin\tfrac{3\pi}4 = \tfrac{\sqrt2}2$, y el ángulo de $[-\tfrac\pi2, \tfrac\pi2]$ con ese seno es $\tfrac\pi4$, no $\tfrac{3\pi}4$.|$\arcsin(\sin\tfrac{3\pi}4)$：$\sin\tfrac{3\pi}4 = \tfrac{\sqrt2}2$、区間内でその sin をもつのは $\tfrac\pi4$（$\tfrac{3\pi}4$ ではない）。|$\arcsin(\sin\tfrac{3\pi}4)$：$\sin\tfrac{3\pi}4 = \tfrac{\sqrt2}2$，区间内正弦为此值的角是 $\tfrac\pi4$——不是 $\tfrac{3\pi}4$。`,
      a: [F(R`\sin\tfrac{3\pi}4 = \tfrac{\sqrt2}2`), Y(R`\arcsin\left(\sin\tfrac{3\pi}4\right) = \tfrac\pi4`)] },
    { a: [F(R`\arccos\left(\cos\tfrac{5\pi}{3}\right)`)],
      ex: { k: 'val', v: 'pi/3', q: R`Find $\arccos\left(\cos\tfrac{5\pi}{3}\right)$.|Calculez $\arccos\left(\cos\tfrac{5\pi}{3}\right)$.|Calcula $\arccos\left(\cos\tfrac{5\pi}{3}\right)$.|$\arccos\left(\cos\tfrac{5\pi}{3}\right)$ を求めよ。|求 $\arccos\left(\cos\tfrac{5\pi}{3}\right)$。`,
        sol: [R`\cos\tfrac{5\pi}3 = \tfrac12`, R`\arccos\tfrac12 = \tfrac\pi3 \in [0, \pi]`] } });

  lesson('Equations and inverse functions/Useful identity', 'arcsin x + arccos x = π/2|arcsin x + arccos x = π/2|arcsen x + arccos x = π/2|arcsin x + arccos x = π/2|arcsin x + arccos x = π/2',
    { s: R`If $\sin\alpha = x$, then the complementary angle $\tfrac\pi2 - \alpha$ has cosine $x$. So the angle whose sine is $x$ and the angle whose cosine is $x$ always add up to a right angle.|Si $\sin\alpha = x$, l’angle complémentaire $\tfrac\pi2 - \alpha$ a pour cosinus $x$. L’angle de sinus $x$ et l’angle de cosinus $x$ font donc toujours un angle droit à eux deux.|Si $\sin\alpha = x$, el ángulo complementario $\tfrac\pi2 - \alpha$ tiene coseno $x$. Así, el ángulo cuyo seno es $x$ y el ángulo cuyo coseno es $x$ siempre suman un recto.|$\sin\alpha = x$ なら余角 $\tfrac\pi2 - \alpha$ の cos は $x$。sin が $x$ の角と cos が $x$ の角の和は常に直角。|若 $\sin\alpha = x$，余角 $\tfrac\pi2 - \alpha$ 的余弦就是 $x$。所以正弦为 $x$ 的角与余弦为 $x$ 的角之和总是直角。`,
      a: [Y(R`\arcsin x + \arccos x = \frac\pi2`, { s: 30 }), AX([-1.3, 1.3], [-1.8, 3.4]), P('y=asin(x)'), P('y=acos(x)', 'b'), P('y=asin(x)+acos(x)', 'g', { d: 500 })] },
    { s: R`$\arcsin\tfrac12 + \arccos\tfrac12 = \tfrac\pi6 + \tfrac\pi3 = \tfrac\pi2$. The green line on the graph is constant: the sum never changes.|$\arcsin\tfrac12 + \arccos\tfrac12 = \tfrac\pi6 + \tfrac\pi3 = \tfrac\pi2$. La droite verte est constante : la somme ne change jamais.|$\arcsin\tfrac12 + \arccos\tfrac12 = \tfrac\pi6 + \tfrac\pi3 = \tfrac\pi2$. La recta verde es constante: la suma nunca cambia.|$\arcsin\tfrac12 + \arccos\tfrac12 = \tfrac\pi6 + \tfrac\pi3 = \tfrac\pi2$。緑の線は一定。|$\arcsin\tfrac12 + \arccos\tfrac12 = \tfrac\pi6 + \tfrac\pi3 = \tfrac\pi2$。绿线是常数。`,
      a: [Y(R`\tfrac\pi6 + \tfrac\pi3 = \tfrac\pi2`)] },
    { a: [F(R`\arcsin x = \tfrac\pi5`)],
      ex: { k: 'val', v: '3pi/10', q: R`If $\arcsin x = \tfrac\pi5$, find $\arccos x$.|Si $\arcsin x = \tfrac\pi5$, calculez $\arccos x$.|Si $\arcsin x = \tfrac\pi5$, halla $\arccos x$.|$\arcsin x = \tfrac\pi5$ のとき $\arccos x$ を求めよ。|若 $\arcsin x = \tfrac\pi5$，求 $\arccos x$。`,
        sol: [R`\arccos x = \tfrac\pi2 - \tfrac\pi5`, R`= \tfrac{3\pi}{10}`] } });

  Cheats.tutor('trigonometry', L);
})();
